2452	
2453	  if (!companion_bridge_test_sensor_take(&cmd))
2454	    {
2455	      return;
2456	    }
2457	
2458	  switch (cmd)
2459	    {
2460	      case COMPANION_TEST_SENSOR_SCAN:
2461	        if (ble_sensor_connect_busy())
2462	          {
