2467	        ble_sensor_set_connect(false);
2468	        ble_sensor_set_adv_debug(false);
2469	        if (ble_sensor_start(ins) != 0)
2470	          {
2471	            LOGE("sensor scan start failed");
2472	            break;
2473	          }
2474	
2475	        ble_sensor_scan_arm(companion_bridge_test_sensor_scan_ms());
2476	        break;
2477	
2478	      case COMPANION_TEST_SENSOR_CONNECT:
2479	        {
2480	          /* 先取走 kind：一次性，失败也不留在桥里粘给下一条命令。
2481	           * AUTO（0xff）＝按 ADV 里第一个匹配的类型，NSH / ctl 走这条；
2482	           * 菜单点选会带上当前页面的类型。 */
2483	          uint8_t kind = companion_bridge_sensor_cmd_take_connect_kind();
2484	
2485	          if (ble_sensor_start(ins) != 0)
2486	            {
2487	              LOGE("sensor connect start failed");
2488	              break;
2489	            }
2490	
2491	          if (ble_sensor_connect_index_kind(
2492	                  companion_bridge_test_sensor_connect_idx(), kind) != 0)
2493	            {
2494	              break;
2495	            }
2496	        }
2497	
2498	        break;
2499	
2500	      case COMPANION_TEST_SENSOR_CONNECT_ADDR:
2501	        {
2502	          struct companion_sensor_bind bind;
2503	
2504	          companion_bridge_sensor_cmd_get_bind(&bind);
2505	          if (ble_sensor_start(ins) != 0)
2506	            {
2507	              LOGE("sensor addr connect start failed");
2508	              break;
2509	            }
2510	
2511	          if (ble_sensor_connect_addr(bind.addr, bind.addr_type, bind.kind,
2512	                                      bind.name, bind.drop_addr,
2513	                                      bind.drop_kind) != 0)
2514	            {
2515	              LOGE("sensor addr connect failed");
2516	            }
2517	        }
2518	        break;
2519	
2520	      case COMPANION_TEST_SENSOR_CLEAR_WANT:
2521	        {
2522	          struct companion_sensor_bind bind;
2523	
2524	          companion_bridge_sensor_cmd_get_bind(&bind);
2525	          (void)ble_sensor_clear_want(bind.addr, bind.kind);
2526	        }
2527	        break;
2528	
2529	      case COMPANION_TEST_SENSOR_SCAN_STOP:
2530	        ble_sensor_scan_stop();
2531	        break;
2532	
2533	      case COMPANION_TEST_SENSOR_DISCONNECT:
2534	        ble_sensor_disconnect_all();
2535	        break;
2536	
2537	      case COMPANION_TEST_SENSOR_DISCONNECT_KIND:
2538	        (void)ble_sensor_disconnect_kind(companion_bridge_test_sensor_kind());
2539	        break;
2540	
2541	      case COMPANION_TEST_SENSOR_STOP:
2542	        ble_sensor_stop();
