2556	/**
2557	 * @brief 主循环一拍：传感器泵、FS 泵、状态标志、心跳 notify。
2558	 *
2559	 * 文件 I/O 在 companion_fs_pump()；本任务优先级低于 CONFIG_BT_LONG_WQ_PRIO，
2560	 * 避免 SD 等待饿死协议栈。禁止 statfs()。
2561	 */
2562	static void companion_tick(uint32_t start_ms, uint32_t *last_notify_ms)
2563	{
2564	  uint8_t      buf[COMPANION_STATUS_WIRE_LEN];
2565	  bt_address_t peer;
2566	  uint32_t     now = mono_ms();
2567	  bool         send = false;
2568	  bool         usb_busy = xfer_usb_busy();
2569	  bool         fs_busy  = companion_fs_busy();
2570	  bool         drop_phone_gnss = false;
2571	  bool         ride_session = false;
2572	  bool         ride_moving = false;
2573	  uint8_t      ready;
2574	
2575	  ready = ble_sensor_ready_mask();
2576	  companion_bridge_ride_get(&ride_session, &ride_moving);
2577	
2578	  pthread_mutex_lock(&g_ctx.lock);
2579	
2580	  g_ctx.status.uptime_sec = myvendor_mono_elapsed_ms(now, start_ms) / 1000;
2581	
2582	  {
2583	    int bat = myvendor_sys_battery_percent_cached();
2584	    uint8_t bat_wire = (bat < 0 || bat > 100) ?
2585	                       COMPANION_BATTERY_UNKNOWN : (uint8_t)bat;
2586	
2587	    if (g_ctx.status.battery_pct != bat_wire)
2588	      {
2589	        g_ctx.status.battery_pct = bat_wire;
2590	        g_ctx.status_dirty = true;
2591	      }
2592	  }
2593	
2594	  status_set_flags(ride_session ? COMPANION_STATUS_RECORDING : 0,
2595	                   ride_session ? 0 : COMPANION_STATUS_RECORDING);
2596	  status_set_flags(ride_moving ? COMPANION_STATUS_MOVING : 0,
2597	                   ride_moving ? 0 : COMPANION_STATUS_MOVING);
2598	
2599	  if (fs_busy)
2600	    {
2601	      status_set_flags(COMPANION_STATUS_FS_BUSY, 0);
2602	    }
2603	  else
2604	    {
2605	      status_set_flags(0, COMPANION_STATUS_FS_BUSY);
2606	    }
2607	
2608	  if (usb_busy)
2609	    {
2610	      status_set_flags(COMPANION_STATUS_USB_MTP_BUSY, 0);
2611	    }
2612	  else
2613	    {
2614	      status_set_flags(0, COMPANION_STATUS_USB_MTP_BUSY);
2615	    }
2616	
2617	  /** App 不再推送后清掉 GPS_PHONE（过期的手机定位）。 */
2618	
2619	  if ((g_ctx.status.flags & COMPANION_STATUS_GPS_PHONE) != 0 &&
2620	      myvendor_mono_elapsed_ms(now, g_ctx.last_gnss_ms) >=
2621	      COMPANION_GNSS_STALE_SEC * 1000)
2622	    {
2623	      status_set_flags(0, COMPANION_STATUS_GPS_PHONE);
2624	      g_ctx.fix_valid = false;
2625	      drop_phone_gnss = true;
2626	    }
2627	
2628	  status_set_flags((ready & (1u << 0)) ? COMPANION_STATUS_SENSOR_HR : 0,
2629	                   (ready & (1u << 0)) ? 0 : COMPANION_STATUS_SENSOR_HR);
2630	  status_set_flags((ready & (1u << 1)) ? COMPANION_STATUS_SENSOR_CSC : 0,
2631	                   (ready & (1u << 1)) ? 0 : COMPANION_STATUS_SENSOR_CSC);
2632	  status_set_flags((ready & (1u << 2)) ? COMPANION_STATUS_SENSOR_CPS : 0,
2633	                   (ready & (1u << 2)) ? 0 : COMPANION_STATUS_SENSOR_CPS);
2634	
2635	  status_pack(&g_ctx.status, buf);
2636	
2637	  /* "连着但手机不说话"探针已在 2026-09-18 移除。
2638	   *
2639	   * 它把"手机在不在说话"绑在 0xFF14 的 1–5 Hz 推送上了，而按用户的决定 App
2640	   * 以后不做辅助定位、手机位置只在用得到的时候带一次 —— 这条判据就没有意义了
2641	   * （会把正常的按需连接一律报成"静默"）。链路是否还活着改由
2642	   * `companion_link_watchdog()` 用**控制器有没有回话**（HCI 活动）判定，与 App
2643	   * 的数据节奏无关。 */
2644	
2645	  if (g_ctx.connected && g_ctx.ccc_enabled)
2646	    {
2647	      send = g_ctx.notify_req || g_ctx.status_dirty ||
2648	             (myvendor_mono_elapsed_ms(now, *last_notify_ms) >=
2649	              COMPANION_STATUS_HEARTBEAT_SEC * 1000);
2650	    }
2651	
2652	  peer = g_ctx.peer;
2653	  g_ctx.notify_req   = false;
2654	  g_ctx.status_dirty = false;
2655	  pthread_mutex_unlock(&g_ctx.lock);
2656	
2657	  if (drop_phone_gnss)
2658	    {
2659	      companion_bridge_gnss_clear();
2660	    }
2661	
2662	  /** 可读值与 notify 保持一致，避免 0xFF12 普通读和通知对不上。 */
2663	
2664	  if (g_gatts_handle != NULL)
2665	    {
2666	      bt_gatts_set_attr_value(g_gatts_handle, COMP_STATUS_ID, buf,
2667	                              sizeof(buf));
2668	    }
2669	
2670	  /** FS Data notify 突发已经很压控制器。中间插状态心跳会让 Android 把 0xFF16 收成最后一片。 */
2671	
2672	  if (send && !fs_busy)
2673	    {
2674	      /** 连续失败 = 链路已经不送货了（最典型的是缓冲区被占住：往死链路 notify，
2675	       *  借走的 PDU 要等拆链才归还，池子被慢慢抽干 —— 现场 `myvendor net_buf:
2676	       *  pool ... empty for 2000 ms, giving up` 每 5 s 一条就是这么来的）。
2677	       *
2678	       *  处理分两段，都不新造 API：
2679	       *    1) **降频探测**：一旦失败，就不再按心跳频率打，改成每
2680	       *       COMPANION_NOTIFY_PROBE_MS 试一次 —— 立刻止住"继续借 buffer"，
2681	       *       同时保留探测能力（链路自己好了能恢复）；
2682	       *    2) **如实断开**：连续 COMPANION_NOTIFY_STARVE_N 次仍失败，就交给既有
2683	       *       的 adapter cycle 拆链重连（断开会让 stack 归还 PDU，池子随之恢复；
2684	       *       `le_disconnected()` 回调负责把 connected 清掉，状态与手机侧一致）。
2685	       *       带冷却，避免抖动。
2686	       *
2687	       *  不在这里直接清 g_ctx.connected：让真正的断开事件去清，避免状态分叉。
2688	       */
2689	      static uint8_t  s_fail_n;        /* 连续 notify 失败次数 */
2690	      static uint32_t s_probe_ms;      /* 上次探测（含成功）的时刻 */
2691	      static uint32_t s_cycle_ms;      /* 上次判死拆链的时刻（冷却基准） */
2692	      bool probe = true;
2693	
2694	      if (s_fail_n > 0 && s_probe_ms != 0 &&
2695	          myvendor_mono_elapsed_ms(now, s_probe_ms) <
2696	              COMPANION_NOTIFY_PROBE_MS)
2697	        {
2698	          probe = false;
2699	        }
2700	
2701	      if (probe)
2702	        {
2703	          bt_status_t ret;
2704	
2705	          s_probe_ms = now;
2706	          companion_bridge_phase_set("notify");
2707	          ret = bt_gatts_notify(g_gatts_handle, &peer, COMP_STATUS_ID,
2708	                                buf, sizeof(buf));
2709	          if (ret == BT_STATUS_SUCCESS)
2710	            {
2711	              *last_notify_ms = now;
2712	              g_notify_err = BT_STATUS_SUCCESS;
2713	              s_fail_n = 0;
2714	            }
2715	          else
2716	            {
2717	              if (ret != g_notify_err)
2718	                {
2719	                  /** 状态特征从不 notify 在 App 看来像死机。仅在错误变化时打印，避免断链刷屏。 */
2720	
2721	                  LOGE("status notify failed: %d", (int)ret);
2722	                  g_notify_err = ret;
2723	                }
2724	
2725	              if (s_fail_n < 0xffu)
2726	                {
2727	                  s_fail_n++;
2728	                }
2729	
2730	              if (s_fail_n >= COMPANION_NOTIFY_STARVE_N &&
2731	                  (s_cycle_ms == 0 ||
2732	                   myvendor_mono_elapsed_ms(now, s_cycle_ms) >=
2733	                       COMPANION_NOTIFY_CYCLE_COOLDOWN_MS))
2734	                {
2735	                  s_cycle_ms = now;
2736	                  s_fail_n   = 0;
2737	                  LOGE("status notify dead x%u (last=%d), adapter cycle",
2738	                       (unsigned)COMPANION_NOTIFY_STARVE_N, (int)ret);
2739	                  ble_supervisor_request_cycle(BLE_SUPERVISOR_FAULT_ADAPTER,
2740	                                               now);
2741	                }
2742	            }
2743	        }
2744	    }
2745	}
