1	/**
2	 * @file myvendor_usbdev.c
3	 * @brief USB 控制器电源：arch 早初始化已 `arm_usbinitialize()`，此后由本文件接管。
4	 *
5	 * `ctl mtp off` 卸 MTP gadget，再 `arm_usbuninitialize()`：关 PHY、复位 USBC、
6	 * 停 USBC 时钟。不碰 BLE FS，也不拆 `mtp_simple` worker。
7	 *
8	 * SPDX-License-Identifier: Apache-2.0
9	 */
10	
11	#include "myvendor_usbdev.h"
12	
13	#include <nuttx/config.h>
14	
15	#include <errno.h>
16	#include <stdbool.h>
17	#include <syslog.h>
18	
19	#ifdef CONFIG_USBMTP
20	#  include <nuttx/usb/mtp.h>
21	#endif
22	
23	#if defined(CONFIG_USBDEV) || defined(CONFIG_SF32LB52_USBDEV)
24	extern void arm_usbinitialize(void);
25	extern void arm_usbuninitialize(void);
26	
27	static bool g_hw_known;
28	static bool g_hw_up;
29	#ifdef CONFIG_USBMTP
30	static void *g_gadget;
31	#endif
32	
33	/**
34	 * @brief 首次调用时认定 arch 已把 USBC 拉起来。
35	 */
36	static void assume_arch_usb(void)
37	{
38	  if (!g_hw_known)
39	    {
40	      g_hw_up = true;
41	      g_hw_known = true;
42	    }
43	}
44	#endif
45	
46	int myvendor_usbdev_set(bool on)
47	{
48	#if defined(CONFIG_USBDEV) || defined(CONFIG_SF32LB52_USBDEV)
49	  assume_arch_usb();
50	
51	  if (on)
52	    {
53	      if (!g_hw_up)
54	        {
55	          arm_usbinitialize();
56	          g_hw_up = true;
57	          syslog(LOG_INFO, "usbdev: controller on\n");
58	        }
59	
60	#ifdef CONFIG_USBMTP
61	      if (g_gadget == NULL)
62	        {
63	          g_gadget = usbdev_mtp_initialize();
64	          if (g_gadget == NULL)
65	            {
66	              syslog(LOG_ERR, "usbdev: usbdev_mtp_initialize failed\n");
67	              return -ENODEV;
68	            }
69	
70	          syslog(LOG_INFO, "usbdev: MTP gadget bound\n");
71	        }
72	#endif
73	
74	      return 0;
75	    }
76	
77	#ifdef CONFIG_USBMTP
78	  if (g_gadget != NULL)
79	    {
80	      usbdev_mtp_uninitialize(g_gadget);
81	      g_gadget = NULL;
82	      syslog(LOG_INFO, "usbdev: MTP gadget unbound\n");
83	    }
84	#endif
85	
86	  if (g_hw_up)
87	    {
88	      arm_usbuninitialize();
89	      g_hw_up = false;
90	      syslog(LOG_INFO, "usbdev: controller off (PHY+USBC clk)\n");
91	    }
92	
93	  return 0;
94	#else
95	  (void)on;
96	  return -ENOTSUP;
97	#endif
98	}
99	
100	bool myvendor_usbdev_get(void)
101	{
102	#if defined(CONFIG_USBDEV) || defined(CONFIG_SF32LB52_USBDEV)
103	  assume_arch_usb();
104	  return g_hw_up;
105	#else
106	  return false;
107	#endif
108	}
