1	/**
2	 * @file board_mtp.c
3	 * @brief 按需 MTP：USB 控制器与 MTP 类驱动由 mtp_responder 应用持有（LAZY 模式）。
4	 *
5	 * CONFIG_MTP_RESPONDER_LAZY 下，board bringup 不初始化 USB；mtp_responder 启动时
6	 * 才 arm_usbinitialize + usbdev_mtp_initialize，退出时释放。
7	 *
8	 * SPDX-License-Identifier: Apache-2.0
9	 */
10	
11	#include <nuttx/config.h>
12	
13	#ifdef CONFIG_MTP_RESPONDER_LAZY
14	
15	#include "mtp_board.h"
16	#include "mtp_simple/mtp_features.h"
17	
18	#include <errno.h>
19	#include <stdbool.h>
20	#include <syslog.h>
21	#include <unistd.h>
22	
23	#include <nuttx/usb/mtp.h>
24	
25	extern void arm_usbinitialize(void);
26	extern void arm_usbuninitialize(void);
27	extern void board_usb_lazy_enable(bool enable);
28	
29	static void *g_mtp_usb_handle;
30	static pid_t g_mtp_pid;
31	static bool g_mtp_usb_hw_up;
32	static bool g_mtp_usb_drv_up;
33	
34	/**
35	 * @brief MTP USB 驱动与 responder 是否都在运行。
36	 */
37	bool board_mtp_is_running(void)
38	{
39	  return g_mtp_usb_drv_up && g_mtp_pid > 0;
40	}
41	
42	/** @brief 主机断开：卸载 MTP 类驱动。 */
43	void board_mtp_host_disconnect(void)
44	{
45	  if (g_mtp_usb_drv_up && g_mtp_usb_handle != NULL)
46	    {
47	      usbdev_mtp_uninitialize(g_mtp_usb_handle);
48	      g_mtp_usb_handle = NULL;
49	      g_mtp_usb_drv_up = false;
50	    }
51	}
52	
53	/** @brief 断开 MTP 并关闭 USB 硬件。 */
54	void board_mtp_host_reset(void)
55	{
56	  board_mtp_host_disconnect();
57	
58	  if (g_mtp_usb_hw_up)
59	    {
60	      arm_usbuninitialize();
61	      board_usb_lazy_enable(false);
62	      g_mtp_usb_hw_up = false;
63	    }
64	}
65	
66	/**
67	 * @brief mtp_responder 启动：拉起 USB 与 MTP 驱动。
68	 * @param pid responder 进程 pid。
69	 */
70	void board_mtp_app_running(pid_t pid)
71	{
72	  if (g_mtp_usb_drv_up)
73	    {
74	      g_mtp_pid = pid;
75	      return;
76	    }
77	
78	  if (!g_mtp_usb_hw_up)
79	    {
80	      board_usb_lazy_enable(true);
81	      arm_usbinitialize();
82	      g_mtp_usb_hw_up = true;
83	    }
84	
85	  g_mtp_usb_handle = usbdev_mtp_initialize();
86	  if (g_mtp_usb_handle == NULL)
87	    {
88	      syslog(LOG_ERR, "board_mtp: usbdev_mtp_initialize failed\n");
89	      board_mtp_host_reset();
90	      return;
91	    }
92	
93	  g_mtp_usb_drv_up = true;
94	  g_mtp_pid = pid;
95	#if MTP_FEAT_INFO
96	  syslog(LOG_INFO, "board_mtp: USB MTP up (pid=%ld)\n", (long)pid);
97	#endif
98	}
99	
100	/** @brief mtp_responder 退出：释放 USB/MTP 资源。 */
101	void board_mtp_app_exited(void)
102	{
103	  pid_t pid = g_mtp_pid;
104	
105	  board_mtp_host_reset();
106	  g_mtp_pid = 0;
107	
108	  if (pid > 0)
109	    {
110	#if MTP_FEAT_INFO
111	      syslog(LOG_INFO, "board_mtp: resources released (pid=%ld)\n",
112	             (long)pid);
113	#endif
114	    }
