35	static void put_le32(uint8_t *p, uint32_t v)
36	{
37	  p[0] = (uint8_t)(v & 0xff);
38	  p[1] = (uint8_t)((v >> 8) & 0xff);
39	  p[2] = (uint8_t)((v >> 16) & 0xff);
40	  p[3] = (uint8_t)((v >> 24) & 0xff);
41	}
