43	/** @brief 向路径追加一个组件（拒绝 ..）。 */
44	static int append_component(char *out, size_t *olen, size_t outsz,
45	                            const char *comp, size_t clen)
46	{
47	  if (clen == 0 || (clen == 1 && comp[0] == '.'))
48	    {
49	      return 0;
50	    }
51	
52	  if (clen == 2 && comp[0] == '.' && comp[1] == '.')
53	    {
54	      return EINVAL;
55	    }
56	
57	  if (*olen + 1 + clen >= outsz)
58	    {
59	      return ENAMETOOLONG;
60	    }
61	
62	  out[(*olen)++] = '/';
63	  memcpy(out + *olen, comp, clen);
64	  *olen += clen;
65	  out[*olen] = '\0';
66	  return 0;
67	}
