88	/** @brief 计算已有文件 CRC32 与大小（续传用）。 */
89	static int hash_existing(const char *path, uint32_t *crc, uint32_t *size)
90	{
91	  uint8_t buf[256];
92	  int     fd;
93	  ssize_t n;
94	
95	  *crc  = 0;
96	  *size = 0;
97	
98	  fd = open(path, O_RDONLY);
99	  if (fd < 0)
100	    {
101	      return errno == ENOENT ? 0 : (errno != 0 ? errno : EIO);
102	    }
103	
104	  while ((n = read(fd, buf, sizeof(buf))) > 0)
105	    {
106	      *crc   = crc32part(buf, (size_t)n, *crc);
107	      *size += (uint32_t)n;
108	    }
109	
110	  close(fd);
111	  if (n < 0)
112	    {
113	      return errno != 0 ? errno : EIO;
114	    }
115	
116	  return 0;
117	}
