119	/** @brief 跳过绝对路径中的已知根前缀。 */
120	static int skip_abs_root(const char *in, size_t inlen, const char *root,
121	                         const char **rest, size_t *restlen)
122	{
123	  size_t n = strlen(root);
124	
125	  if (inlen < n || memcmp(in, root, n) != 0)
126	    {
127	      return 0;
128	    }
129	
130	  if (inlen > n && in[n] != '/')
131	    {
132	      return 0;
133	    }
134	
135	  *rest    = in + n;
136	  *restlen = inlen - n;
137	  return 1;
138	}
