140	/** @brief 判断是否 OTA/fw 路径请求。 */
141	static int ota_request(const char *in, size_t inlen,
142	                       const char **rest, size_t *restlen)
143	{
144	  const char *p;
145	  size_t      n;
146	
147	  if (in == NULL || inlen == 0)
148	    {
149	      return 0;
150	    }
151	
152	  if (skip_abs_root(in, inlen, XFER_OTA_ROOT, rest, restlen) ||
153	      skip_abs_root(in, inlen, "/mnt/lfs/fw", rest, restlen))
154	    {
155	      return 1;
156	    }
157	
158	  p = in;
159	  n = inlen;
160	  while (n > 0 && *p == '/')
161	    {
162	      p++;
163	      n--;
164	    }
165	
166	  if (n >= 2 && p[0] == 'f' && p[1] == 'w' && (n == 2 || p[2] == '/'))
167	    {
168	      *rest    = p + 2;
169	      *restlen = n - 2;
170	      return 1;
171	    }
172	
173	  return 0;
174	}
