176	/** @brief 判断是否崩溃日志路径请求。 */
177	static int coredump_request(const char *in, size_t inlen,
178	                            const char **rest, size_t *restlen)
179	{
180	  const char *p;
181	  size_t      n;
182	
183	  if (in == NULL || inlen == 0)
184	    {
185	      return 0;
186	    }
187	
188	  if (skip_abs_root(in, inlen, XFER_COREDUMP_ROOT, rest, restlen))
189	    {
190	      return 1;
191	    }
192	
193	  p = in;
194	  n = inlen;
195	  while (n > 0 && *p == '/')
196	    {
197	      p++;
198	      n--;
199	    }
200	
201	  if (n >= 8 && memcmp(p, "coredump", 8) == 0 && (n == 8 || p[8] == '/'))
202	    {
203	      *rest    = p + 8;
204	      *restlen = n - 8;
205	      return 1;
206	    }
207	
208	  return 0;
209	}
