211	/** @brief 判断是否诊断日志路径请求。 */
212	static int diag_request(const char *in, size_t inlen,
213	                        const char **rest, size_t *restlen)
214	{
215	  const char *p;
216	  size_t      n;
217	
218	  if (in == NULL || inlen == 0)
219	    {
220	      return 0;
221	    }
222	
223	  if (skip_abs_root(in, inlen, XFER_DIAG_ROOT, rest, restlen))
