247	/** @brief 判断是否常用点 TSV 路径请求。 */
248	static int fav_request(const char *in, size_t inlen)
249	{
250	  const char *p;
251	  size_t      n;
252	
253	  if (in == NULL || inlen == 0)
254	    {
255	      return 0;
256	    }
257	
258	  if (inlen == sizeof(XFER_FAV_PATH) - 1 &&
259	      memcmp(in, XFER_FAV_PATH, sizeof(XFER_FAV_PATH) - 1) == 0)
260	    {
261	      return 1;
262	    }
263	
264	  p = in;
265	  n = inlen;
266	  while (n > 0 && *p == '/')
267	    {
268	      p++;
269	      n--;
270	    }
271	
272	  if (n == 9 && memcmp(p, "favorites", 9) == 0)
273	    {
274	      return 1;
275	    }
276	
277	  if (n == 13 && memcmp(p, "favorites.tsv", 13) == 0)
278	    {
279	      return 1;
280	    }
281	
282	  if (n == sizeof("kv/bicycle_favorites.tsv") - 1 &&
283	      memcmp(p, "kv/bicycle_favorites.tsv",
284	             sizeof("kv/bicycle_favorites.tsv") - 1) == 0)
285	    {
286	      return 1;
287	    }
288	
289	  return 0;
290	}
