292	/** @brief 在 root 下解析相对路径组件。 */
293	static int resolve_under(const char *root, const char *in, size_t inlen,
294	                         char *out, size_t outsz)
295	{
296	  size_t rootlen = strlen(root);
297	  size_t i;
298	  size_t olen;
299	  int    ret;
300	
301	  if (out == NULL || outsz < rootlen + 1)
302	    {
303	      return EINVAL;
304	    }
305	
306	  memcpy(out, root, rootlen);
307	  out[rootlen] = '\0';
308	  olen = rootlen;
309	
310	  if (in == NULL || inlen == 0)
311	    {
312	      return 0;
313	    }
314	
315	  i = 0;
316	  while (i < inlen)
317	    {
318	      const char *comp;
319	      size_t      clen;
320	
321	      while (i < inlen && in[i] == '/')
322	        {
323	          i++;
324	        }
325	
326	      if (i >= inlen)
327	        {
328	          break;
329	        }
330	
331	      comp = in + i;
332	      clen = 0;
333	      while (i + clen < inlen && in[i + clen] != '/')
334	        {
335	          clen++;
336	        }
337	
338	      ret = append_component(out, &olen, outsz, comp, clen);
339	      if (ret != 0)
340	        {
341	          return ret;
342	        }
343	
344	      i += clen;
345	    }
346	
347	  return 0;
348	}
