350	/** @brief 确保 OTA 根目录存在。 */
351	static void ensure_ota_dir(const char *path)
352	{
353	  size_t n = sizeof(XFER_OTA_ROOT) - 1;
354	
355	  if (path == NULL)
356	    {
357	      return;
358	    }
359	
360	  if (strncmp(path, XFER_OTA_ROOT, n) != 0)
361	    {
362	      return;
363	    }
364	
365	  if (path[n] != '\0' && path[n] != '/')
366	    {
367	      return;
368	    }
369	
370	  (void)mkdir(XFER_OTA_ROOT, 0777);
371	}
