471	/**
472	 * @brief 查询路径 stat。
473	 * @return 0 成功，正数 errno。
474	 */
475	int xfer_stat(const char *path, struct xfer_stat *out)
476	{
477	  struct stat st;
478	
479	  if (path == NULL || out == NULL)
480	    {
481	      return EINVAL;
482	    }
483	
484	  if (stat(path, &st) != 0)
485	    {
486	      return errno != 0 ? errno : EIO;
487	    }
488	
489	  out->type  = S_ISDIR(st.st_mode) ? 1 : 0;
490	  out->size  = (uint32_t)st.st_size;
491	  out->mtime = (uint32_t)st.st_mtime;
492	  return 0;
493	}
