495	/**
496	 * @brief 打包目录列表页。
497	 * @return 字节数或负 errno。
498	 */
499	int xfer_list_pack(const char *dir, uint16_t *cursor, uint8_t *out,
500	                   uint16_t out_max, bool *last)
501	{
502	  DIR           *dp;
503	  struct dirent *ent;
504	  uint16_t       skip;
505	  uint16_t       packed = 0;
506	  uint16_t       off = 0;
507	  int            err = 0;
508	
509	  if (dir == NULL || cursor == NULL || out == NULL || last == NULL)
510	    {
511	      return -EINVAL;
512	    }
513	
514	  *last = false;
515	  skip  = *cursor;
516	
517	  dp = opendir(dir);
518	  if (dp == NULL)
519	    {
520	      return errno != 0 ? -errno : -EIO;
521	    }
522	
523	  while ((ent = readdir(dp)) != NULL)
524	    {
525	      struct xfer_stat st;
526	      char             full[XFER_PATH_MAX];
527	      size_t           nlen;
528	      uint16_t         need;
529	      int              ret;
530	
531	      if (xfer_entry_skipped(ent->d_name))
532	        {
533	          continue;
534	        }
535	
536	      if (skip > 0)
537	        {
538	          skip--;
539	          continue;
540	        }
541	
542	      nlen = strlen(ent->d_name);
543	      if (nlen > 255)
544	        {
545	          nlen = 255;
546	        }
547	
548	      need = (uint16_t)(1 + 4 + 4 + 1 + nlen);
549	      if (off + need > out_max)
550	        {
551	          /* This page is full; caller will resume with the updated cursor. */
552	
553	          goto done;
554	        }
555	
556	      ret = snprintf(full, sizeof(full), "%s/%s", dir, ent->d_name);
557	      if (ret < 0 || (size_t)ret >= sizeof(full))
558	        {
559	          continue;
560	        }
561	
562	      ret = xfer_stat(full, &st);
563	      if (ret != 0)
564	        {
565	          continue;
566	        }
567	
568	      out[off] = st.type;
569	      put_le32(out + off + 1, st.size);
570	      put_le32(out + off + 5, st.mtime);
571	      out[off + 9] = (uint8_t)nlen;
572	      memcpy(out + off + 10, ent->d_name, nlen);
573	      off    = (uint16_t)(off + need);
574	      packed++;
575	    }
576	
577	  *last = true;
578	
579	done:
580	  if (closedir(dp) != 0 && err == 0)
581	    {
582	      err = errno;
583	    }
584	
585	  *cursor = (uint16_t)(*cursor + packed);
586	  if (err != 0)
587	    {
588	      return -err;
589	    }
590	
591	  return (int)off;
592	}
