615	int xfer_read_seek(int fd, uint32_t offset)
616	{
617	  if (fd < 0)
618	    {
619	      return EINVAL;
620	    }
621	
622	  if (lseek(fd, (off_t)offset, SEEK_SET) == (off_t)-1)
623	    {
