630	/** @brief 从保持的读 fd 读数据。 */
631	int xfer_read_data(int fd, uint8_t *buf, uint16_t len, uint16_t *got)
632	{
633	  ssize_t n;
634	
635	  if (fd < 0 || buf == NULL || got == NULL)
636	    {
637	      return EINVAL;
638	    }
639	
640	  *got = 0;
641	  n = read(fd, buf, len);
642	  if (n < 0)
643	    {
644	      return errno != 0 ? errno : EIO;
645	    }
646	
647	  *got = (uint16_t)n;
648	  return 0;
649	}
