660	int xfer_read(const char *path, uint32_t offset, uint8_t *buf, uint16_t len,
661	              uint16_t *got)
662	{
663	  int fd;
664	  int ret;
665	
666	  if (got != NULL)
667	    {
668	      *got = 0;
669	    }
670	
671	  ret = xfer_read_open(path, &fd);
672	  if (ret != 0)
673	    {
674	      return ret;
675	    }
676	
677	  ret = xfer_read_seek(fd, offset);
678	  if (ret != 0)
679	    {
680	      xfer_read_close(fd);
681	      return ret;
682	    }
683	
684	  ret = xfer_read_data(fd, buf, len, got);
685	  xfer_read_close(fd);
686	  return ret;
687	}
