743	/** @brief 重命名并同步 .part 旁路。 */
744	int xfer_rename(const char *from, const char *to)
745	{
746	  char from_part[XFER_PATH_MAX];
747	  char to_part[XFER_PATH_MAX];
748	
749	  if (from == NULL || to == NULL)
750	    {
751	      return EINVAL;
752	    }
753	
754	  if (rename(from, to) != 0)
755	    {
756	      return errno != 0 ? errno : EIO;
757	    }
758	
759	  if (make_part_path(from, from_part, sizeof(from_part)) == 0 &&
