245	  size_t o = 0;
246	
247	  if (dstsz == 0)
248	    {
249	      return;
250	    }
251	
252	  while (src[i] != '\0' && o + 1 < dstsz)
253	    {
254	      char c = src[i++];
255	
256	      if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
257	          (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')
258	        {
259	          dst[o++] = c;
260	        }
261	      else
262	        {
263	          dst[o++] = '_';
264	        }
265	    }
266	
267	  dst[o] = '\0';
268	}
