272	 */
273	static void icon_basename(char *dst, size_t dstsz, const char *src)
274	{
275	  const char *base = src;
276	  const char *p;
277	
278	  for (p = src; *p != '\0'; p++)
279	    {
280	      if (*p == '/' || *p == '\\')
281	        {
282	          base = p + 1;
283	        }
284	    }
285	
286	  sanitize_pkg(dst, dstsz, base);
287	  if (strcmp(dst, ".") == 0 || strcmp(dst, "..") == 0)
288	    {
289	      dst[0] = '\0';
290	    }
291	}
