293	/**
294	 * @brief 一条完整的 0xFF17 消息；`test notif on` 时打印。
295	 */
296	static void notif_complete(const uint8_t *payload, uint16_t len, uint8_t type)
297	{
298	  const uint8_t *title_v = NULL;
299	  const uint8_t *body_v  = NULL;
300	  const uint8_t *pkg_v   = NULL;
301	  const uint8_t *icon_v  = NULL;
302	  const uint8_t *name_v  = NULL;
303	  uint16_t title_l = 0;
304	  uint16_t body_l  = 0;
305	  uint16_t pkg_l   = 0;
306	  uint16_t icon_l  = 0;
307	  uint16_t name_l  = 0;
308	  char title[COMPANION_NOTIF_TITLE_MAX + 1];
309	  char body[COMPANION_NOTIF_BODY_MAX + 1];
310	  char pkg[COMPANION_NOTIF_PACKAGE_MAX + 1];
311	  char icon_name[COMPANION_NOTIF_ICON_NAME_MAX + 1];
312	  char icon_abs[XFER_PATH_MAX];
313	  char rel[96];
314	  const char *show_title;
315	  bool found = false;
316	
317	  tlv_find(payload, len, COMPANION_NOTIF_TAG_TITLE, &title_v, &title_l);
318	  tlv_find(payload, len, COMPANION_NOTIF_TAG_BODY, &body_v, &body_l);
319	  tlv_find(payload, len, COMPANION_NOTIF_TAG_PACKAGE, &pkg_v, &pkg_l);
320	  tlv_find(payload, len, COMPANION_NOTIF_TAG_ICON, &icon_v, &icon_l);
321	  tlv_find(payload, len, COMPANION_NOTIF_TAG_APP_NAME, &name_v, &name_l);
322	
323	  title[0] = '\0';
324	  body[0]  = '\0';
325	  pkg[0]   = '\0';
326	  icon_name[0] = '\0';
327	  icon_abs[0] = '\0';
328	
329	  if (title_v != NULL)
330	    {
331	      copy_trunc(title, sizeof(title), title_v, title_l);
332	    }
333	  else if (name_v != NULL)
334	    {
335	      copy_trunc(title, sizeof(title), name_v, name_l);
336	    }
337	
338	  if (body_v != NULL)
339	    {
340	      copy_trunc(body, sizeof(body), body_v, body_l);
341	    }
342	
343	  if (pkg_v != NULL)
344	    {
345	      char raw[COMPANION_NOTIF_PACKAGE_MAX + 1];
346	
347	      copy_trunc(raw, sizeof(raw), pkg_v, pkg_l);
348	      sanitize_pkg(pkg, sizeof(pkg), raw);
349	    }
350	
351	  if (icon_v != NULL && icon_l > 0)
352	    {
353	      char raw[COMPANION_NOTIF_ICON_NAME_MAX + 1];
354	
355	      copy_trunc(raw, sizeof(raw), icon_v, icon_l);
356	      icon_basename(icon_name, sizeof(icon_name), raw);
357	    }
358	  else if (pkg[0] != '\0')
359	    {
360	      snprintf(icon_name, sizeof(icon_name), "%s.png", pkg);
361	      if (strcmp(icon_name, ".") == 0 || strcmp(icon_name, "..") == 0)
362	        {
363	          icon_name[0] = '\0';
364	        }
365	    }
366	
367	  strip_bar(title);
368	  strip_bar(body);
369	
370	  show_title = title[0] != '\0' ? title : "通知";
371	  if (body[0] == '\0')
372	    {
373	      strncpy(body, show_title, sizeof(body) - 1);
374	      body[sizeof(body) - 1] = '\0';
375	    }
376	
377	  if (companion_bridge_test_notif_get())
378	    {
379	      LOGI("notif type=%u title=%s body=%s icon=%s", (unsigned)type,
380	           show_title, body, icon_name[0] != '\0' ? icon_name : "-");
381	    }
382	
383	  if (!companion_bridge_policy_notif())
384	    {
385	      return;
386	    }
387	
388	  if (companion_bridge_policy_calls_only() &&
389	      type != COMPANION_NOTIF_TYPE_CALL)
390	    {
391	      return;
392	    }
393	
394	  if (icon_name[0] != '\0')
395	    {
396	      snprintf(rel, sizeof(rel), "%s/%s", COMPANION_NOTIF_ICON_DIR, icon_name);
397	      if (xfer_resolve(rel, strlen(rel), icon_abs, sizeof(icon_abs)) == 0 &&
398	          companion_fs_icon_usable(icon_abs))
399	        {
400	          found = true;
401	        }
402	      else
403	        {
404	          companion_fs_need_file(icon_name);
405	          icon_abs[0] = '\0';
406	        }
407	    }
408	
409	  {
410	    struct companion_notif_item item;
411	
412	    memset(&item, 0, sizeof(item));
413	    item.type = type;
414	    strncpy(item.title, show_title, sizeof(item.title) - 1);
415	    strncpy(item.body, body, sizeof(item.body) - 1);
416	    if (found)
417	      {
418	        strncpy(item.icon, icon_abs, sizeof(item.icon) - 1);
419	      }
420	
421	    companion_bridge_notif_post(&item);
422	  }
423	}
