428	static void nav_complete(const uint8_t *payload, uint16_t len, uint8_t flags)
429	{
430	  uint8_t  n;
431	  uint8_t  i;
432	  int32_t  lat[COMPANION_NAV_MAX_PTS] = {0};
433	  int32_t  lon[COMPANION_NAV_MAX_PTS] = {0};
434	
435	  if (len < COMPANION_NAV_PT_LEN || (len % COMPANION_NAV_PT_LEN) != 0)
436	    {
437	      LOGE("nav payload len %u not a multiple of %u", len,
438	           COMPANION_NAV_PT_LEN);
439	      return;
440	    }
441	
442	  n = (uint8_t)(len / COMPANION_NAV_PT_LEN);
443	  if (n > COMPANION_NAV_MAX_PTS)
444	    {
445	      n = COMPANION_NAV_MAX_PTS;
446	    }
447	
448	  for (i = 0; i < n; i++)
449	    {
450	      lat[i] = (int32_t)get_le32(payload + (uint16_t)i * COMPANION_NAV_PT_LEN);
451	      lon[i] = (int32_t)get_le32(payload + (uint16_t)i * COMPANION_NAV_PT_LEN + 4);
452	    }
453	
454	  companion_bridge_nav_store(lat, lon, n);
455	  if (companion_bridge_test_ctrl_get())
456	    {
457	      LOGI("nav %u pts start=%d (print only, no UI)", n,
458	           (flags & COMPANION_NAV_FLAG_START) != 0);
459	      for (i = 0; i < n && i < 8; i++)
460	        {
461	          LOGI("  [%u] lat_e7=%ld lon_e7=%ld", i,
462	               (long)lat[i], (long)lon[i]);
463	        }
464	
465	      if (n > 8)
466	        {
467	          LOGI("  ... %u more", (unsigned)(n - 8));
468	        }
469	    }
470	}
