196	  if (g_fs.wbuf == NULL)
197	    {
198	      g_fs.wbuf = board_malloc_psram(FS_WBUF_SIZE);
199	      if (g_fs.wbuf != NULL)
200	        {
201	          g_fs.wbuf_cap = FS_WBUF_SIZE;
202	          LOGI("fs write cache %u KiB in PSRAM",
203	               (unsigned)(FS_WBUF_SIZE / 1024));
204	        }
205	      else
206	        {
207	          LOGE("fs write cache PSRAM alloc failed, write-through");
208	        }
209	    }
