240	/** @brief 从读缓冲或 LFS 取数据（含 RLE 解码）。 */
241	static int rbuf_get(uint32_t off, uint8_t *dst, uint16_t want, uint16_t *got)
242	{
243	  uint16_t copied = 0;
244	  int      ret;
245	
246	  *got = 0;
247	  if (want == 0)
248	    {
249	      return 0;
250	    }
251	
252	  if (g_fs.rfd < 0)
253	    {
254	      return xfer_read(g_fs.path, off, dst, want, got);
255	    }
256	
257	  while (copied < want)
258	    {
259	      uint16_t n;
260	      uint16_t loaded = 0;
261	
262	      if (g_fs.rbuf != NULL && g_fs.rbuf_len > 0 &&
263	          off >= g_fs.rbuf_off &&
264	          off < g_fs.rbuf_off + g_fs.rbuf_len)
265	        {
266	          uint32_t idx = off - g_fs.rbuf_off;
267	          uint32_t have = g_fs.rbuf_len - idx;
268	
269	          n = (uint16_t)have;
270	          if (n > (uint16_t)(want - copied))
271	            {
272	              n = (uint16_t)(want - copied);
273	            }
274	
275	          memcpy(dst + copied, g_fs.rbuf + idx, n);
276	          copied = (uint16_t)(copied + n);
277	          off += n;
278	          continue;
279	        }
280	
281	      if (g_fs.rfd_pos != off)
282	        {
283	          ret = xfer_read_seek(g_fs.rfd, off);
284	          if (ret != 0)
285	            {
286	              return ret;
287	            }
288	
289	          g_fs.rfd_pos = off;
290	        }
291	
292	      if (g_fs.rbuf != NULL && g_fs.rbuf_cap > 0)
293	        {
294	          uint16_t load_n = (uint16_t)g_fs.rbuf_cap;
295	
296	          ret = xfer_read_data(g_fs.rfd, g_fs.rbuf, load_n, &loaded);
297	          if (ret != 0)
298	            {
299	              return ret;
300	            }
301	
302	          g_fs.rbuf_off = off;
303	          g_fs.rbuf_len = loaded;
304	          g_fs.rfd_pos  = off + loaded;
305	          if (loaded == 0)
306	            {
307	              break;
308	            }
309	
310	          continue;
311	        }
312	
313	      n = (uint16_t)(want - copied);
314	      ret = xfer_read_data(g_fs.rfd, dst + copied, n, &loaded);
315	      if (ret != 0)
316	        {
317	          return ret;
318	        }
319	
320	      g_fs.rfd_pos += loaded;
321	      copied = (uint16_t)(copied + loaded);
322	      off += loaded;
323	      if (loaded == 0)
324	        {
325	          break;
326	        }
327	    }
328	
329	  *got = copied;
330	  return 0;
331	}
