335	/** @brief 让出 SD/LFS，避免 CLOSE 尾部把 UI 线程饿死。 */
336	static void wbuf_yield(void)
337	{
338	  /** 主循环的心跳也在这里续上 —— "在写盘" 不是 "线程停摆"。
339	   *
340	   *  why：CLOSE 已应答后的延迟补写（`fs_deferred_commit()`）跑在 companion
341	   *  线程上，它调的 `wbuf_flush()` 会**同步**排空整个写缓存；而 `wbuf_append()`
342	   *  缓存满时的那两个排空循环同样在一个调用里连写很多块。一个满 cache
343	   *  （`FS_WBUF_SIZE` = 256 KiB）按 `FS_FLUSH_CHUNK`(4 KiB) 一块块写，实测
344	   *  每块 ~290 ms（`usleep(2000)` 只占 2 ms，其余是 LittleFS 在 SD 上的
345	   *  写），整段 18~19 s。
346	   *
347	   *  心跳只在 `ble_companion.c` 主循环顶上喂一次，于是这一整段里
348	   *  `companion_bridge_heartbeat_age_ms()` 会一路涨过 diag 的
349	   *  `DIAG_BLE_THREAD_MS`(15 s)，判成"线程停摆"→ SIGKILL 掉一个正在写盘的
350	   *  线程，再往后是 LCPU force reset / adapter not ready / respawn 失败 ——
351	   *  现场那次 388 KB 的 GPX 导入就是这么把自己写死的。
352	   *
353	   *  这里续心跳不会削弱 diag 的本意：`diag_ble_restart()` 要抓的是"堵在
354	   *  不可中断 HCI 等待上"，那种情况下这个循环根本不在跑，也就没人喂心跳。
355	   *  watchdog 不必在这里补 —— SD 的 PIO 忙等里 `sd1_spin_yield()` 已经每
356	   *  1 ms 喂过一次（见 chips/sf32lb52/sf32lb_sdio.c）。
357	   */
358	  companion_bridge_heartbeat();
359	  usleep(2000);
360	}
