369	/** @brief 写出写缓冲一个 chunk。 */
370	static int wbuf_flush_chunk(void)
371	{
372	  uint32_t n;
373	  int      ret;
374	
375	  if (g_fs.wbuf_len == 0)
376	    {
377	      return 0;
378	    }
379	
380	  if (g_fs.wfd < 0)
381	    {
382	      g_fs.wbuf_len = 0;
383	      return EINVAL;
384	    }
385	
386	  n = g_fs.wbuf_len;
387	  if (n > FS_FLUSH_CHUNK)
388	    {
389	      n = FS_FLUSH_CHUNK;
390	    }
391	
392	  ret = xfer_write_data(g_fs.wfd, g_fs.wbuf, n);
393	  if (ret != 0)
394	    {
395	      LOGI("fs write flush failed errno=%d n=%lu got=%lu",
396	           ret, (unsigned long)n, (unsigned long)g_fs.w_got);
397	      return ret;
398	    }
399	
400	  {
401	    uint32_t before = g_fs.w_flushed;
402	
403	    g_fs.w_flushed += n;
404	    if (before == 0u ||
405	        (before / (32u * 1024u)) != (g_fs.w_flushed / (32u * 1024u)))
406	      {
407	        LOGI("fs write flushed %lu/%lu",
408	             (unsigned long)g_fs.w_flushed,
409	             (unsigned long)g_fs.w_expected);
410	      }
411	
412	    /* OTA 在 /mnt/kv：不定期 fsync 的话，复位后 LittleFS 会回到
413	     * WRITE_OPEN 时的 size，刚写的一两兆续传就没了。 */
414	    if (path_is_ota_fw(g_fs.path) &&
415	        (before / FS_SYNC_BYTES) != (g_fs.w_flushed / FS_SYNC_BYTES))
416	      {
417	        myvendor_watchdog_work_beat();
418	        myvendor_watchdog_hw_pet();
419	        (void)fsync(g_fs.wfd);
420	        myvendor_watchdog_hw_pet();
421	        LOGI("fs write synced %lu/%lu",
422	             (unsigned long)g_fs.w_flushed,
423	             (unsigned long)g_fs.w_expected);
424	      }
425	  }
426	
427	  if (n < g_fs.wbuf_len)
428	    {
429	      memmove(g_fs.wbuf, g_fs.wbuf + n, g_fs.wbuf_len - n);
430	    }
431	
432	  g_fs.wbuf_len -= n;
433	  return 0;
434	}
435	
436	static int wbuf_flush(void)
437	{
438	  int ret;
439	
440	  while (g_fs.wbuf_len > 0)
441	    {
442	      ret = wbuf_flush_chunk();
443	      if (ret != 0)
444	        {
445	          return ret;
446	        }
447	
448	      if (g_fs.wbuf_len > 0)
449	        {
450	          wbuf_yield();
451	        }
452	    }
453	
454	  return 0;
455	}
