457	/** @brief 追加明文到写缓冲（必要时 flush）。 */
458	static int wbuf_append(const uint8_t *p, uint16_t n)
459	{
460	  int ret;
461	
462	  if (n == 0)
463	    {
464	      return 0;
465	    }
466	
467	  if (g_fs.wbuf == NULL || g_fs.wbuf_cap == 0)
468	    {
469	      return xfer_write_data(g_fs.wfd, p, n);
470	    }
471	
472	  while (g_fs.wbuf_len + n > g_fs.wbuf_cap)
473	    {
474	      ret = wbuf_flush_chunk();
475	      if (ret != 0)
476	        {
477	          return ret;
478	        }
479	
480	      wbuf_yield();
481	    }
482	
483	  if (n > g_fs.wbuf_cap)
484	    {
485	      return xfer_write_data(g_fs.wfd, p, n);
486	    }
487	
488	  memcpy(g_fs.wbuf + g_fs.wbuf_len, p, n);
489	  g_fs.wbuf_len += n;
490	
491	  /* 满 4KiB 就写。否则 BLE 先把整文件堆进 RAM，环满丢包。 */
492	  if (wbuf_stream_disk())
493	    {
494	      while (g_fs.wbuf_len >= FS_FLUSH_CHUNK)
495	        {
496	          ret = wbuf_flush_chunk();
497	          if (ret != 0)
498	            {
499	              return ret;
500	            }
501	
502	          wbuf_yield();
503	        }
504	    }
505	
506	  return 0;
507	}
