520	/**
521	 * @brief 睡到 kick 或超时。
522	 * @param timeout_ms 最长等待。
523	 */
524	void companion_fs_wait(uint32_t timeout_ms)
525	{
526	  struct timespec ts;
527	
528	  if (!g_fs_wake_ready)
529	    {
530	      usleep(timeout_ms * 1000);
531	      return;
532	    }
533	
534	  while (sem_trywait(&g_fs_wake) == 0)
535	    {
536	    }
537	
538	  if (timeout_ms == 0)
539	    {
540	      return;
541	    }
542	
543	  clock_gettime(CLOCK_REALTIME, &ts);
544	  ts.tv_sec += (time_t)(timeout_ms / 1000);
545	  ts.tv_nsec += (long)(timeout_ms % 1000) * 1000000L;
546	  if (ts.tv_nsec >= 1000000000L)
547	    {
548	      ts.tv_sec++;
549	      ts.tv_nsec -= 1000000000L;
550	    }
551	
552	  (void)sem_timedwait(&g_fs_wake, &ts);
553	  while (sem_trywait(&g_fs_wake) == 0)
554	    {
555	    }
556	}
