567	/** @brief 写入小端 uint16。 */
568	static void put_le16(uint8_t *p, uint16_t v)
569	{
570	  p[0] = (uint8_t)(v & 0xff);
571	  p[1] = (uint8_t)(v >> 8);
572	}
573	
574	/** @brief 写入小端 uint32。 */
575	static void put_le32(uint8_t *p, uint32_t v)
576	{
577	  p[0] = (uint8_t)(v & 0xff);
578	  p[1] = (uint8_t)((v >> 8) & 0xff);
579	  p[2] = (uint8_t)((v >> 16) & 0xff);
580	  p[3] = (uint8_t)((v >> 24) & 0xff);
581	}
582	
583	/** @brief 读出小端 uint16。 */
584	static uint16_t get_le16(const uint8_t *p)
585	{
586	  return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
587	}
588	
589	/** @brief 读出小端 uint32。 */
590	static uint32_t get_le32(const uint8_t *p)
591	{
592	  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
593	         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
594	}
