596	/** @brief errno 映射为协议 uint8 错误码。 */
597	static uint8_t errno_u8(int err)
598	{
599	  if (err < 0)
600	    {
601	      err = -err;
602	    }
603	
604	  if (err <= 0)
605	    {
606	      return 0;
607	    }
608	
609	  if (err > 255)
610	    {
611	      return 255;
612	    }
613	
614	  return (uint8_t)err;
615	}
