617	/** @brief 当前 ATT MTU 下 FS notify 载荷预算。 */
618	static uint16_t payload_budget(void)
619	{
620	  uint32_t att;
621	
622	  att = (g_fs.mtu > 3) ? (g_fs.mtu - 3) : 20;
623	  if (att < COMPANION_FS_HDR_LEN + 1)
624	    {
625	      return 0;
626	    }
627	
628	  att -= COMPANION_FS_HDR_LEN;
629	  if (att > sizeof(g_fs.tx) - COMPANION_FS_HDR_LEN)
630	    {
631	      att = sizeof(g_fs.tx) - COMPANION_FS_HDR_LEN;
632	    }
