658	static void fs_deferred_commit(void);
659	
660	/** @brief 重置 FS 会话状态。 */
661	static void session_reset(bool drop_part)
662	{
663	  if (g_fs.commit_pending)
664	    {
665	      g_fs.commit_pending = false;
666	      fs_deferred_commit();
667	    }
668	  else if (g_fs.wfd >= 0)
669	    {
670	      if (drop_part)
671	        {
672	          g_fs.wbuf_len = 0;
673	          xfer_write_abort(g_fs.wfd, g_fs.tmp_path);
674	        }
675	      else
676	        {
677	          (void)wbuf_flush();
678	          xfer_write_suspend(g_fs.wfd);
679	        }
680	
681	      g_fs.wfd = -1;
682	    }
683	  else
684	    {
685	      g_fs.wbuf_len = 0;
686	    }
687	
688	  read_fd_close();
689	  release_lfs();
690	  g_fs.state    = FS_IDLE;
691	  g_fs.tx_len   = 0;
692	  g_fs.seq      = 0;
693	  g_fs.rx_seq   = 0;
694	  g_fs.data_q_n = 0;
695	  g_fs.data_q_rd = 0;
696	  g_fs.tmp_path[0] = '\0';
697	  g_fs.inflight    = 0;
698	  g_fs.w_fail      = 0;
699	  g_fs.w_rle       = false;
700	  g_fs.r_rle       = false;

1850	    }
1851	
1852	  frame[0] = g_fs.cmd;
1853	  frame[1] = g_fs.tid;
1854	  frame[2] = flags;
1855	  frame[3] = g_fs.tx_status;
1856	  put_le16(frame + 4, g_fs.seq);
1857	  put_le16(frame + 6, g_fs.tx_len);
1858	  if (g_fs.tx_len > 0)
1859	    {
1860	      memcpy(frame + COMPANION_FS_HDR_LEN, g_fs.tx, g_fs.tx_len);
1861	    }
1862	
1863	  ret = bt_gatts_notify(g_fs.handle, &g_fs.peer, g_fs.data_attr,
1864	                        frame, (uint16_t)(COMPANION_FS_HDR_LEN + g_fs.tx_len));
1865	  if (ret != BT_STATUS_SUCCESS)
1866	    {
1867	      g_diag_notify_fail++;
1868	      LOGE("fs notify failed: %d", (int)ret);
1869	      return false;
1870	    }
1871	
1872	  g_diag_notify_sent++;
1873	
1874	  if (g_fs.inflight < 255)
1875	    {
1876	      g_fs.inflight++;
1877	    }
1878	
1879	  g_fs.send_ms = fs_now_ms();
1880	  g_fs.seq++;
1881	  g_fs.tx_len = 0;
1882	  if (g_fs.tx_last && g_fs.state != FS_WRITE)
1883	    {
1884	      g_fs.state = FS_IDLE;
1885	    }
1886	
1887	  g_fs.tx_last = false;
1888	  g_fs.tx_err  = false;
1889	  return true;
1890	}
