2002	/**
2003	 * @brief 拷贝一次 0xFF15 命令写；真正 I/O 在 companion_fs_pump()。
2004	 */
2005	uint16_t companion_fs_on_cmd(const uint8_t *value, uint16_t length)
2006	{
2007	  if (value == NULL || length == 0)
2008	    {
2009	      return 0;
2010	    }
2011	
2012	  if (length > sizeof(g_fs.cmd_req.buf))
2013	    {
2014	      length = sizeof(g_fs.cmd_req.buf);
2015	    }
2016	
2017	  pthread_mutex_lock(&g_fs.lock);
2018	  memcpy(g_fs.cmd_req.buf, value, length);
2019	  g_fs.cmd_req.len     = length;
2020	  g_fs.cmd_req.pending = true;
2021	  pthread_mutex_unlock(&g_fs.lock);
2022	  companion_fs_kick();
2023	  return length;
2024	}
