2026	/**
2027	 * @brief 拷贝一次 0xFF16 数据写；真正 I/O 在 companion_fs_pump()。
2028	 */
2029	uint16_t companion_fs_on_data(const uint8_t *value, uint16_t length)
2030	{
2031	  uint16_t wr;
2032	  int      waits = 0;
2033	  static unsigned s_drop_log;
2034	
2035	  if (value == NULL || length == 0)
2036	    {
2037	      return 0;
2038	    }
2039	
2040	  if (length > FS_SLOT_MAX)
2041	    {
2042	      length = FS_SLOT_MAX;
2043	    }
2044	
2045	  pthread_mutex_lock(&g_fs.lock);
2046	  if (g_fs.data_q == NULL || g_fs.data_q_cap == 0)
2047	    {
2048	      fs_buffers_init();
2049	    }
2050	
2051	  while (g_fs.data_q != NULL && g_fs.data_q_cap != 0 &&
2052	         g_fs.data_q_n >= g_fs.data_q_cap && waits < FS_ENQ_WAIT_MAX)
2053	    {
2054	      pthread_mutex_unlock(&g_fs.lock);
2055	      companion_fs_kick();
2056	      usleep(FS_ENQ_WAIT_US);
2057	      waits++;
2058	      pthread_mutex_lock(&g_fs.lock);
2059	    }
2060	
2061	  if (g_fs.data_q == NULL || g_fs.data_q_cap == 0 ||
2062	      g_fs.data_q_n >= g_fs.data_q_cap)
2063	    {
2064	      pthread_mutex_unlock(&g_fs.lock);
2065	      if ((s_drop_log++ & 63) == 0)
2066	        {
2067	          LOGE("fs data queue full, drop %u (x%u)",
2068	               (unsigned)length, s_drop_log);
2069	        }
2070	
2071	      return 0;
2072	    }
2073	
2074	  wr = (uint16_t)((g_fs.data_q_rd + g_fs.data_q_n) % g_fs.data_q_cap);
2075	  memcpy(g_fs.data_q[wr].buf, value, length);
2076	  g_fs.data_q[wr].len = length;
2077	  g_fs.data_q_n++;
2078	  pthread_mutex_unlock(&g_fs.lock);
2079	  companion_fs_kick();
2080	  return length;
2081	}
