2133	/**
2134	 * @brief companion 线程上的 FS 工作函数。
2135	 * @return 还有未完成工作则为 true。
2136	 */
2137	bool companion_fs_pump(void)
2138	{
2139	  uint8_t  cmd_buf[FS_STAGING_MAX];
2140	  uint16_t cmd_len = 0;
2141	  uint8_t  data_buf[FS_SLOT_MAX];
2142	  uint16_t data_len = 0;
2143	  bool     abort = false;
2144	  bool     busy;
2145	  int      drained = 0;
2146	
2147	  pthread_mutex_lock(&g_fs.lock);
2148	  if (g_fs.abort_req)
2149	    {
2150	      if (g_fs.commit_pending)
2151	        {
2152	          g_fs.abort_req = false;
2153	        }
2154	      else
2155	        {
2156	          g_fs.abort_req = false;
2157	          abort = true;
2158	          g_fs.data_q_n = 0;
2159	          g_fs.data_q_rd = 0;
2160	        }
2161	    }
2162	
2163	  if (g_fs.cmd_req.pending)
2164	    {
2165	      cmd_len = g_fs.cmd_req.len;
2166	      memcpy(cmd_buf, g_fs.cmd_req.buf, cmd_len);
2167	      g_fs.cmd_req.pending = false;
2168	    }
2169	
2170	  pthread_mutex_unlock(&g_fs.lock);
2171	
2172	  if (abort)
2173	    {
2174	      pthread_mutex_lock(&g_fs.lock);
2175	      session_reset(true);
2176	      pthread_mutex_unlock(&g_fs.lock);
2177	      LOGI("fs abort");
2178	    }
2179	
2180	  /* WRITE_CLOSE lives on the command characteristic.  Drain queued DATA
2181	   * first so the last packets are in the PSRAM cache (and CRC) before we
2182	   * commit.  Other commands still run first so WRITE_OPEN beats leftover
2183	   * DATA from a previous transfer.
2184	   */
2185	
2186	  if (cmd_len > 0 && cmd_buf[0] == COMPANION_FS_WRITE_CLOSE)
2187	    {
2188	      unsigned drained_close = 0;
2189	
2190	      /* 先把环里的 DATA 解到 RAM 算 CRC，不要在应答前写 /mnt/lfs。
2191	       * App 无响应写 1 秒把整文件塞进环，再立刻 CLOSE；若这里落盘，
2192	       * 第一次 lfs_alloc（地图盘很满）会卡数秒，手机进度条和导入列表一起死。 */
2193	      g_fs.disk_hold = true;
2194	      while (true)
2195	        {
2196	          pthread_mutex_lock(&g_fs.lock);
2197	          if (g_fs.data_q_n == 0 || g_fs.data_q == NULL ||
2198	              g_fs.data_q_cap == 0)
2199	            {
2200	              pthread_mutex_unlock(&g_fs.lock);
2201	              break;
2202	            }
2203	
2204	          data_len = g_fs.data_q[g_fs.data_q_rd].len;
2205	          memcpy(data_buf, g_fs.data_q[g_fs.data_q_rd].buf, data_len);
2206	          g_fs.data_q_rd =
2207	            (uint16_t)((g_fs.data_q_rd + 1) % g_fs.data_q_cap);
2208	          g_fs.data_q_n--;
2209	          pthread_mutex_unlock(&g_fs.lock);
2210	          dispatch_data(data_buf, data_len);
2211	          drained_close++;
2212	          if ((drained_close & 31u) == 0u)
2213	            {
2214	              wbuf_yield();
2215	            }
2216	        }
2217	
2218	      g_fs.disk_hold = false;
2219	
2220	      /* CLOSE 应答不要握着 g_fs.lock。落盘在 notify 之后。 */
2221	      dispatch_cmd(cmd_buf, cmd_len);
2222	    }
2223	  else
2224	    {
