1491	          logged = true;
1492	          LOGI("fs disabled in factory; copy files over USB MTP");
1493	        }
1494	
1495	      queue_err(cmd, tid, EACCES);
1496	      return;
1497	    }
1498	
1499	  if (xfer_usb_busy())
1500	    {
1501	      queue_err(cmd, tid, EBUSY);
1502	      return;
1503	    }
1504	
1505	  /* A new command aborts an in-flight LIST/READ.  WRITE_CLOSE is the
1506	   * exception: it finishes the WRITE session opened earlier.
1507	   */
1508	
1509	  if (g_fs.state != FS_IDLE && g_fs.state != FS_WRITE &&
1510	      cmd != COMPANION_FS_WRITE_CLOSE)
1511	    {
1512	      session_reset(false);
1513	    }
1514	
1515	  /* Each command is its own seq space.  Forgetting this makes STAT/DELETE
1516	   * after LIST start at seq=1; the App then rejects a perfectly good LAST.
1517	   */
1518	
1519	  g_fs.seq = 0;
1520	
1521	  switch (cmd)
1522	    {
1523	      case COMPANION_FS_STATFS:
1524	        handle_statfs(tid);
1525	        break;
1526	
1527	      case COMPANION_FS_LIST:
1528	        handle_list_begin(tid, payload, plen);
1529	        break;
1530	
1531	      case COMPANION_FS_STAT:
1532	        handle_stat(tid, payload, plen);
1533	        break;
1534	
1535	      case COMPANION_FS_READ:
1536	        handle_read_begin(tid, payload, plen);
1537	        break;
1538	
1539	      case COMPANION_FS_WRITE_OPEN:
1540	        handle_write_open(tid, payload, plen);
1541	        break;
1542	
1543	      case COMPANION_FS_WRITE_CLOSE:
1544	        handle_write_close(tid, payload, plen);
1545	        break;
1546	
1547	      case COMPANION_FS_DELETE:
1548	      case COMPANION_FS_MKDIR:
1549	        handle_simple_path(cmd, tid, payload, plen);
1550	        break;
1551	
1552	      case COMPANION_FS_RENAME:
1553	        handle_rename(tid, payload, plen);
1554	        break;
1555	
1556	      default:
1557	        queue_err(cmd, tid, ENOSYS);
1558	        break;
1559	    }
1560	}
1561	
1562	static int rle_write_out(void *ctx, const uint8_t *p, uint16_t n)
1563	{
1564	  int ret;
1565	
1566	  (void)ctx;
1567	  if (n == 0)
1568	    {
1569	      return 0;
1570	    }
1571	
1572	  if (g_fs.w_got > g_fs.w_expected ||
1573	      (uint32_t)n > g_fs.w_expected - g_fs.w_got)
1574	    {
1575	      return EINVAL;
1576	    }
1577	
1578	  ret = wbuf_append(p, n);
1579	  if (ret != 0)
1580	    {
1581	      return ret;
1582	    }
1583	
1584	  g_fs.w_crc = crc32part(p, n, g_fs.w_crc);
1585	  g_fs.w_got += n;
1586	  return 0;
1587	}
