118	/** @brief CLOCK_MONOTONIC 毫秒。 */
119	static uint64_t mtp_monotonic_ms(void)
120	{
121	  struct timespec ts;
122	
123	  clock_gettime(CLOCK_MONOTONIC, &ts);
124	  return (uint64_t)ts.tv_sec * 1000ull + (uint64_t)ts.tv_nsec / 1000000ull;
125	}
