127	/** @brief 活动快照 hold 窗口到期后清零（持锁）。 */
128	static void mtp_activity_expire_locked(uint64_t now_ms)
129	{
130	  if (g_activity_running || g_activity_hold_until_ms == 0)
131	    {
132	      return;
133	    }
134	
135	  if (now_ms >= g_activity_hold_until_ms)
136	    {
137	      memset(&g_activity, 0, sizeof(g_activity));
138	      g_activity.op = MYVENDOR_MTP_OP_IDLE;
139	      g_activity_hold_until_ms = 0;
140	    }
141	}
