162	void myvendor_mtp_activity_start(myvendor_mtp_op_t op, const char *target,
163	                                 uint64_t total_bytes)
164	{
165	  pthread_mutex_lock(&g_mtp_lock);
166	  g_activity_running = true;
167	  g_activity_hold_until_ms = 0;
