209	/** @brief 标记操作结束并进入 hold 窗口供 UI 显示。 */
210	void myvendor_mtp_activity_finish(void)
211	{
212	  uint64_t now_ms = mtp_monotonic_ms();
213	
214	  pthread_mutex_lock(&g_mtp_lock);
215	  g_activity_running = false;
216	  g_activity_hold_until_ms = now_ms + MYVENDOR_MTP_ACTIVITY_HOLD_MS;
217	  g_activity.active = true;
218	  pthread_mutex_unlock(&g_mtp_lock);
219	}
