221	/**
222	 * @brief 复制当前活动快照。
223	 * @param[out] activity 输出；NULL 则 -EINVAL。
224	 * @return 0 成功。
225	 */
226	int myvendor_mtp_get_activity(myvendor_mtp_activity_t *activity)
227	{
228	  uint64_t now_ms;
229	
230	  if (!activity)
231	    {
232	      return -EINVAL;
233	    }
234	
235	  now_ms = mtp_monotonic_ms();
236	  pthread_mutex_lock(&g_mtp_lock);
237	  mtp_activity_expire_locked(now_ms);
238	  *activity = g_activity;
239	  activity->active = g_activity_running ||
240	                     (g_activity_hold_until_ms > 0 &&
241	                      now_ms < g_activity_hold_until_ms);
242	  pthread_mutex_unlock(&g_mtp_lock);
243	  return 0;
244	}
