326	/** @brief I/O 中断链时由 worker 调用。 */
327	void myvendor_mtp_worker_link_lost(void)
328	{
329	  bool was_busy;
330	
331	  pthread_mutex_lock(&g_mtp_lock);
332	  was_busy = g_transfer_active || g_session;
333	  g_transfer_active = false;
334	  g_link_lost = was_busy;
335	  if (was_busy)
336	    {
337	      g_session = false;
338	      mtp_set_plug_locked(MYVENDOR_MTP_PLUG_OFF);
339	    }
340	
341	  pthread_mutex_unlock(&g_mtp_lock);
342	
343	  if (was_busy)
344	    {
345	      mtp_owner_info("myvendor_mtp: link lost during I/O");
346	    }
347	}
