364	 * @brief worker 阻塞直到可开始 poll 或应退出。
365	 * @return true 可开始；false 应退出。
366	 */
367	bool myvendor_mtp_worker_wait_begin(void)
368	{
369	  for (; ; )
370	    {
371	      if (g_shutdown)
372	        {
373	          return false;
374	        }
375	
376	      if (g_transfer_req && g_plug >= MYVENDOR_MTP_PLUG_ENUM)
