439	/**
440	 * @brief 启动后台 mtp_simple worker（幂等）。
441	 * @return 0 成功，负值为错误码。
442	 */
443	int myvendor_mtp_init(void)
444	{
445	#ifdef CONFIG_MYVENDOR_MTP_SIMPLE
446	  posix_spawnattr_t attr;
447	  FAR char *argv[] = { NULL };
448	  int pid;
449	
450	  pthread_mutex_lock(&g_mtp_lock);
451	  g_shutdown = false;
452	  g_link_lost = false;
453	
454	  if (g_worker_pid > 0 && !mtp_worker_alive(g_worker_pid))
455	    {
456	      syslog(LOG_WARNING, "myvendor_mtp: stale worker pid=%ld, respawning",
457	             (long)g_worker_pid);
458	      g_worker_pid = 0;
459	      g_spawn_pending = false;
460	      mtp_reset_protocol_state_locked();
461	    }
462	
463	  if (g_worker_pid > 0 || g_spawn_pending)
464	    {
465	      pthread_mutex_unlock(&g_mtp_lock);
466	      return 0;
467	    }
468	
469	  g_spawn_pending = true;
470	  pthread_mutex_unlock(&g_mtp_lock);
471	
472	  posix_spawnattr_init(&attr);
473	  attr.priority  = CONFIG_MYVENDOR_MTP_SIMPLE_PRIORITY;
474	  attr.stacksize = sizeof(g_mtp_simple_stack);
475	  posix_spawnattr_setstackaddr(&attr, g_mtp_simple_stack);
476	
477	  pid = task_spawn("mtp_simple", mtp_simple_main, NULL, &attr, argv, NULL);
478	  if (pid < 0)
479	    {
480	      pthread_mutex_lock(&g_mtp_lock);
481	      g_spawn_pending = false;
482	      pthread_mutex_unlock(&g_mtp_lock);
483	      syslog(LOG_ERR, "myvendor_mtp: task_spawn failed: %d", pid);
484	      return pid;
485	    }
486	
487	  pthread_mutex_lock(&g_mtp_lock);
488	  g_worker_pid = (pid_t)pid;
489	  g_spawn_pending = false;
