498	/** @brief 请求 shutdown 并等待 worker 退出。 */
499	void myvendor_mtp_deinit(void)
500	{
501	  pid_t pid;
502	  int i;
503	
504	  pthread_mutex_lock(&g_mtp_lock);
505	  g_shutdown = true;
506	  g_transfer_req = false;
507	  g_poll_abort = true;
508	  pid = g_worker_pid;
509	  pthread_mutex_unlock(&g_mtp_lock);
510	  myvendor_mtp_activity_clear();
511	  mtp_owner_info("myvendor_mtp: deinit (worker pid=%ld)", (long)pid);
512	
513	  if (pid > 0)
514	    {
515	      for (i = 0; i < 30; i++)
516	        {
517	          if (!mtp_worker_alive(pid))
518	            {
519	              break;
520	            }
521	
522	          usleep(100 * 1000);
523	        }
524	
525	      if (mtp_worker_alive(pid))
526	        {
527	          /* 先撤 waitdog 再 SIGTERM：worker 此刻多半正睡在定时等待里。 */
528	          myvendor_task_cancel_waitdog(pid, "myvendor_mtp");
529	          kill(pid, SIGTERM);
530	          for (i = 0; i < 10; i++)
531	            {
532	              if (!mtp_worker_alive(pid))
533	                {
534	                  break;
535	                }
536	
537	              usleep(100 * 1000);
538	            }
539	        }
540	    }
541	
542	  pthread_mutex_lock(&g_mtp_lock);
543	  if (!mtp_worker_alive(g_worker_pid))
544	    {
545	      g_worker_pid = 0;
546	      g_spawn_pending = false;
