616	/** @brief 最近几次 lfs hold 的取用者（只用于诊断：残留 hold 归谁）。
617	 *
618	 *  hold 是计数式的、**没有 owner 字段**：泄漏时只知道"有人没还"，不知道是谁。
619	 *  留一圈最近取用记录（谁、什么时候），在判定残留或挡住别人时打出来 ——
620	 *  现场就能直接指名，而不必再从"释放路径在谁手里"往回推。
621	 */
622	#define MYVENDOR_MTP_HOLD_TRACE 4
623	
624	struct mtp_hold_trace_s
625	{
626	  const char *who;
627	  uint32_t    ms;
628	};
629	
630	static struct mtp_hold_trace_s g_hold_trace[MYVENDOR_MTP_HOLD_TRACE];
631	static uint8_t g_hold_trace_next;
632	
633	static void mtp_hold_trace_add(const char *who)
634	{
635	  g_hold_trace[g_hold_trace_next].who = (who != NULL) ? who : "?";
636	  g_hold_trace[g_hold_trace_next].ms = (uint32_t)myvendor_mono_ms();
637	  g_hold_trace_next =
638	      (uint8_t)((g_hold_trace_next + 1u) % MYVENDOR_MTP_HOLD_TRACE);
639	}
640	
641	/** @brief 环形记录按"最老→最新"写成 `who+ageMs`（age 相对当前时刻）。 */
642	static void mtp_hold_trace_fmt(char *buf, size_t n)
643	{
644	  uint32_t now = (uint32_t)myvendor_mono_ms();
645	  size_t k = 0;
646	  uint8_t i;
647	
648	  if (buf == NULL || n == 0u)
649	    {
650	      return;
651	    }
652	
653	  buf[0] = '\0';
654	  for (i = 0; i < MYVENDOR_MTP_HOLD_TRACE; i++)
655	    {
656	      uint8_t idx =
657	          (uint8_t)((g_hold_trace_next + i) % MYVENDOR_MTP_HOLD_TRACE);
658	      int w;
659	
660	      if (g_hold_trace[idx].who == NULL || k + 24u >= n)
661	        {
662	          continue;
663	        }
664	
665	      w = snprintf(buf + k, n - k, "%s%s+%ums", (k > 0u) ? " " : "",
666	                   g_hold_trace[idx].who,
667	                   (unsigned)(now - g_hold_trace[idx].ms));
668	      if (w <= 0 || (size_t)w >= n - k)
669	        {
670	          buf[k] = '\0';
671	          break;
672	        }
673	
674	      k += (size_t)w;
675	    }
676	
677	  if (k == 0u)
678	    {
679	      snprintf(buf, n, "-");
680	    }
681	}
