699	/** @brief 与 #myvendor_mtp_lfs_hold 配对（计数 -1）。 */
700	void myvendor_mtp_lfs_release(const char *who)
701	{
702	  pthread_mutex_lock(&g_mtp_lock);
703	  if (g_lfs_hold > 0)
704	    {
705	      g_lfs_hold--;
