710	        }
711	    }
712	  else
713	    {
714	      /* 多还了。两种来源：配对写错，或者泄漏的 hold 刚被 quiesce() 回收、
715	       * 晚到的 release 才到。两种都值得知道，但只需知道一次 ——
716	       * 否则又是一条"按次数刷屏"的日志源。 */
717	      static bool underflow_logged;
718	
719	      if (!underflow_logged)
720	        {
721	          underflow_logged = true;
722	          syslog(LOG_WARNING,
723	                 "mtp: lfs_release by %s with hold=0 (多还 / 回收后晚到)\n",
724	                 (who != NULL) ? who : "?");
725	        }
726	    }
