731	/** @brief 自行车/vmap 是否必须推迟 LittleFS I/O。 */
732	bool myvendor_mtp_lfs_quiesce(void)
733	{
734	  bool q;
735	  bool hold_live = false;
736	
737	  pthread_mutex_lock(&g_mtp_lock);
738	
739	  if (g_lfs_hold > 0)
740	    {
741	      /* hold 只在"它附近确实有会话/传输"或"还没过保鲜期"时才算数。
742	       *
743	       * 否则一个**泄漏的残留 hold 会永久挡死星历注入** —— 现场就是
744	       * `xfer=0 hold=1 sess=0 plug=0`：只有 hold 命中，而释放路径要么在
745	       * MTP worker 里（USB 关闭时 worker 不跑），要么在某个提前返回的
746	       * 分支上被漏掉了。手机刚下发的新星历因此被整段丢弃，
747	       * 表现就是"手机推了星历，GNSS 却没同步"。
748	       *
749	       * 保留保鲜期的理由：hold 的本意是"UI/App 马上要用 LFS，别人让一让"，
750	       * 这种预约天然是短时的（秒级）；超过保鲜期还没归还，就是泄漏而不是预约。 */
751	      hold_live = g_session || g_transfer_active ||
752	                  myvendor_mono_elapsed_ms(myvendor_mono_ms(),
753	                                           g_lfs_hold_ms) <
754	                      MYVENDOR_MTP_LFS_HOLD_MAX_MS;
755	
756	      if (!hold_live)
757	        {
758	          /* 泄漏的残留 hold：**在源头回收，而不只是"这次忽略它"**。
759	           *
760	           * 只忽略的话这个计数会永远挂着：下一个取用方从 1 起算（本该从 0），
761	           * 而且每个消费者都得各自等过这 30 s —— 现场就是倒库/注入被白挡
762	           * 二十多秒（还按字节率刷日志）。这里直接清零，让它回到"没人占"；
763	           * 晚到的 release 由下溢保护挡住，不会变成负数。
764	           *
765	           * 这是缺陷信号、不是常态，所以最多打三次。 */
766	          char tr[96];
767	          static uint32_t stale_n;
768	
769	          g_lfs_hold = 0;
770	          g_lfs_hold_ms = 0;
771	
772	          if (stale_n < 3u)
773	            {
774	              stale_n++;
775	              mtp_hold_trace_fmt(tr, sizeof(tr));
776	              syslog(LOG_WARNING,
777	                     "mtp: leaked lfs_hold reclaimed (age>=%u ms, sess=0 xfer=0 "
778	                     "plug=0, last takes: %s) — LFS unblocked\n",
779	                     (unsigned)MYVENDOR_MTP_LFS_HOLD_MAX_MS, tr);
780	            }
781	        }
782	    }
783	
784	  q = g_transfer_active || hold_live
785	      || g_plug >= MYVENDOR_MTP_PLUG_ENUM || g_session;
786	
787	  pthread_mutex_unlock(&g_mtp_lock);
788	  return q;
789	}
