791	void myvendor_mtp_lfs_quiesce_why(char *buf, size_t n)
792	{
793	  bool     xfer;
794	  bool     sess;
795	  int      hold;
796	  unsigned plug;
797	
798	  if (buf == NULL || n == 0u)
799	    {
800	      return;
801	    }
802	
803	  pthread_mutex_lock(&g_mtp_lock);
804	  xfer = g_transfer_active;
805	  hold = g_lfs_hold;
806	  sess = g_session;
807	  plug = (unsigned)g_plug;
808	  pthread_mutex_unlock(&g_mtp_lock);
809	
810	  /* plug 的语义见 myvendor_mtp_plug_t：0=OFF（未插/仅充电）, 1=ENUM, 2=ACTIVE。
811	   * 注意 quiesce 用的是 >= ENUM —— 只要主机选了 MTP 配置就算 busy，哪怕一次
812	   * 传输都没发生。仅充电若不自枚举应停在 0，所以这一项为 1/2 才是可疑点。 */
813	  snprintf(buf, n, "xfer=%d hold=%d sess=%d plug=%u",
814	           xfer ? 1 : 0, hold, sess ? 1 : 0, plug);
815	
816	  /* hold 命中时把"最近是谁取的"也带上：这个字符串会出现在
817	   * `gnss: dbd dump skip (mtp busy: …)` / `eph inject skip (mtp busy: …)`
818	   * 里，于是"谁把 hold 挂住了"在同一行就能看到。 */
819	  if (hold > 0)
820	    {
821	      char tr[96];
822	      size_t used = strlen(buf);
823	
824	      mtp_hold_trace_fmt(tr, sizeof(tr));
825	      snprintf(buf + used, (n > used) ? n - used : 0u,
826	               " hold_by[%s]", tr);
827	    }
828	}
