521	/**
522	 * @brief GATTC 或 HCI 备份确认断链后回收槽位（可重入：已 IDLE 则忽略）。
523	 */
524	static void slot_handle_disconnected(struct sensor_slot *slot)
525	{
526	  char a[BT_ADDR_STR_LENGTH];
527	  bool keep;
528	  bool early;
529	  bool rearm;
530	  uint8_t reason;
531	
532	  if (slot == NULL || slot->state == SENSOR_IDLE)
533	    {
534	      return;
535	    }
536	
537	  bt_addr_ba2str(&slot->addr, a);
538	  keep   = slot_keep_link(slot);
539	  early  = (slot->state == SENSOR_CONNECTING ||
540	            slot->state == SENSOR_DISCOVERING);
541	  rearm  = slot->rearm_adv;
542	  reason = slot->hci_reason;
543	
544	  if (keep)
545	    {
546	      if (early)
547	        {
548	          LOGI("%s connect failed %s, scanning", kind_name(slot->kind), a);
549	        }
550	      else
551	        {
552	          LOGI("%s disconnected %s, scanning to reconnect",
553	               kind_name(slot->kind), a);
554	        }
555	    }
556	  else
557	    {
558	      LOGI("%s disconnected %s", kind_name(slot->kind), a);
559	    }
560	
561	  slot_idle_keep_addr(slot, sensor_now_ms());
562	
563	  if (!keep)
564	    {
565	      uint8_t k = slot->kind;
566	
567	      slot->want_link = false;
568	      /* addr/name 清零与 ble_sensor_owns_addr 的 memcmp 互斥（同 slot_bind_addr）。
569	       * 注意只包住这两行：后面的 slot_bind_addr 自己会加锁，不能嵌套。 */
570	      pthread_mutex_lock(&g_lock);
571	      memset(&slot->addr, 0, sizeof(slot->addr));
572	      memset(slot->name, 0, sizeof(slot->name));
573	      pthread_mutex_unlock(&g_lock);
574	      if (g_pending_bind[k].valid)
575	        {
576	          slot_bind_addr(slot, &g_pending_bind[k].addr,
577	                         g_pending_bind[k].addr_type, 0,
578	                         g_pending_bind[k].name, false);
579	          g_pending_bind[k].valid = false;
580	        }
581	
582	      sensor_ui_publish();
583	      return;
584	    }
585	
586	  if (rearm)
587	    {
588	      slot->adv_seen   = true;
589	      slot->skip_dwell = true;
590	      LOGI("%s already saw advertiser, connect now", kind_name(slot->kind));
591	    }
592	
593	  {
594	    uint32_t cool = SENSOR_RECONNECT_MS;
595	
596	    if (reason == HCI_ERR_CONN_FAIL_TO_ESTAB)
597	      {
598	        cool = SENSOR_RECONNECT_3E_MS;
599	      }
600	    else if (!rearm && (early || sensor_ready_count() >= 1))
601	      {
602	        cool = SENSOR_RECONNECT_BUSY_MS;
603	      }
604	
605	    slot->retry_ms = sensor_now_ms() + cool;
606	  }
607	  sensor_ui_publish();
608	}
