612	 *
613	 * UI 立刻离开「已连接」。回调丢失由健康看门狗重建 GATTC。
614	 */
615	static void slot_begin_disconnect(struct sensor_slot *slot, uint32_t now_ms)
616	{
617	  if (slot == NULL || slot->state == SENSOR_IDLE ||
618	      slot->state == SENSOR_DISCONNECTING)
619	    {
620	      return;
621	    }
622	
623	  slot->state     = SENSOR_DISCONNECTING;
624	  slot->state_ms  = now_ms;
625	  slot->op_sent   = false;
626	  slot->drop_link = false;
627	  LOGI("%s disconnecting", kind_name(slot->kind));
628	  sensor_ui_publish();
629	
630	  if (slot->gatt == NULL ||
631	      bt_gattc_disconnect(slot->gatt) != BT_STATUS_SUCCESS)
632	    {
633	      slot_handle_disconnected(slot);
634	    }
635	}
