1558	/**
1559	 * @brief 在 BAS 仍留在 GATTC 表里时缓存 0x2A19 handle。
1560	 *
1561	 * 板卡 SAL keep_db 后第二次发现不会冲掉该 handle。
1562	 */
1563	static void slot_cache_bat_handle(struct sensor_slot *slot)
1564	{
1565	  bt_uuid_t        uuid;
1566	  gatt_attr_desc_t desc;
1567	
1568	  uuid = BT_UUID_DECLARE_16(UUID_BAT_LEVEL);
1569	  memset(&desc, 0, sizeof(desc));
1570	  if (bt_gattc_get_attribute_by_uuid(slot->gatt, 0x0001, 0xffff,
1571	                                     &uuid, &desc) != BT_STATUS_SUCCESS)
1572	    {
1573	      pthread_mutex_lock(&g_lock);
1574	      slot->bat_h      = 0;
1575	      slot->bat_notify = false;
1576	      slot->feat      &= (uint16_t)~SENSOR_FEAT_BAT;
1577	      pthread_mutex_unlock(&g_lock);
1578	      return;
1579	    }
1580	
1581	  /* 字段写在锁内；SAL 查询本身在锁外（见上）。 */
1582	  pthread_mutex_lock(&g_lock);
1583	  slot->bat_h  = desc.handle;
1584	  slot->feat  |= SENSOR_FEAT_BAT;
1585	  pthread_mutex_unlock(&g_lock);
1586	  LOGD("%s bat handle 0x%04x%s", kind_name(slot->kind),
1587	       (unsigned)slot->bat_h,
1588	       (desc.properties & GATT_PROP_NOTIFY) ? " (notify)" : " (read)");
1589	}
