1591	/**
1592	 * @brief UUID 发现完成：先 BAS 缓存电量 handle，再槽位服务，再订测量和电量。
1593	 *
1594	 * 板卡 SAL 第二次发现追加表，BAS 的 0x2A19 仍可查找/订阅。
1595	 */
1596	static void gattc_on_discovered(gattc_handle_t h, gatt_status_t status,
1597	                                bt_uuid_t *uuid, uint16_t start_handle,
1598	                                uint16_t end_handle)
1599	{
1600	  struct sensor_slot *slot = slot_by_gatt(h);
1601	  uint16_t u16;
1602	  char feats[24];
1603	
1604	  if (slot == NULL)
1605	    {
1606	      return;
1607	    }
1608	
1609	  if (status != GATT_STATUS_SUCCESS)
1610	    {
1611	      if (slot->disc_step == 0)
1612	        {
1613	          LOGI("%s battery skip status %d", kind_name(slot->kind),
1614	               (int)status);
1615	          slot->disc_step = 1;
1616	          slot->state     = SENSOR_DISCOVERING;
1617	          slot->op_sent   = false;
1618	          slot->state_ms  = sensor_now_ms();
1619	          return;
1620	        }
1621	
1622	      LOGE("%s discover status %d", kind_name(slot->kind), (int)status);
1623	      slot->drop_link = true;
1624	      return;
1625	    }
1626	
1627	  if (uuid != NULL && uuid->type != 0)
1628	    {
1629	      u16 = uuid16_of(uuid);
1630	      if (u16 == UUID_HRS)
1631	        {
1632	          slot->feat |= SENSOR_FEAT_HR;
1633	        }
1634	      else if (u16 == UUID_CSCS)
1635	        {
1636	          slot->feat |= SENSOR_FEAT_CSC;
1637	        }
1638	      else if (u16 == UUID_CPS)
1639	        {
1640	          slot->feat |= SENSOR_FEAT_CPS;
1641	        }
1642	
1643	      LOGD("%s svc 0x%04x handles %04x-%04x", kind_name(slot->kind),
1644	           (unsigned)u16, (unsigned)start_handle, (unsigned)end_handle);
1645	      return;
1646	    }
1647	
1648	  mask_str(slot->feat, feats, sizeof(feats));
1649	  LOGD("%s discover done feat=%s", kind_name(slot->kind), feats);
1650	
1651	  if (slot->disc_step == 0)
1652	    {
1653	      /* gattc_locked_discovered 已持锁。slot_cache_bat_handle 内部要查 SAL
1654	       * （bt_gattc_get_attribute_by_uuid），约定是绝不在持锁时碰 SAL —— 否则
1655	       * 一旦该调用需要 service-loop 线程配合，而 service-loop 正等这把锁，
1656	       * 就是死锁。这里显式让出锁，查完再拿回来。 */
1657	      pthread_mutex_unlock(&g_lock);
1658	      slot_cache_bat_handle(slot);
1659	      pthread_mutex_lock(&g_lock);
1660	      slot->disc_step = 1;
1661	      slot->state     = SENSOR_DISCOVERING;
1662	      slot->op_sent   = false;
1663	      slot->state_ms  = sensor_now_ms();
1664	      LOGD("%s discover 0x%04x", kind_name(slot->kind),
1665	           (unsigned)kind_svc_uuid(slot->kind));
1666	      return;
1667	    }
1668	
1669	  if ((slot->feat & kind_feat_bit(slot->kind)) == 0)
1670	    {
1671	      LOGE("%s discover missing 0x%04x", kind_name(slot->kind),
1672	           (unsigned)kind_svc_uuid(slot->kind));
1673	      slot->drop_link = true;
1674	      return;
1675	    }
1676	
1677	  slot->state    = SENSOR_SUBSCRIBING;
1678	  slot->state_ms = sensor_now_ms();
1679	  slot->op_sent  = false;
1680	  slot->sub_step = 0;
1681	}
