3112	      sensor_age_ms(now_ms, g_health_log_ms) < SENSOR_HEALTH_LOG_MS)
3113	    {
3114	      return;
3115	    }
3116	
3117	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
