3119	      if (g_slots[i].want_link || g_slots[i].state != SENSOR_IDLE)

3166	static void sensor_health_pump(uint32_t now_ms)
3167	{
3168	  /* 瞬时让位**派生**上报：正在扫描或正在建链 → 不要在此时抢广播。
3169	   * 电平语义、每拍都报一次，所以不存在"谁忘了收回"那种闩锁泄漏。 */
3170	  companion_ble_post(COMPANION_BLE_EV_TRANSIENT, 0,
3171	                     sensor_hci_connecting() || g_scanner != NULL, false);
3172	  uint8_t i;
3173	
3174	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
3175	    {
3176	      struct sensor_slot *slot = &g_slots[i];
3177	      uint8_t  reason;
3178	      uint8_t  state;
3179	      bool     act;
3180	
3181	      /* 锁内只做"读标志 + 清事件 + 快照判断依据"，出锁后再跑状态机与 HCI。
3182	       *
3183	       * hci_gone 的读-清必须与回调的置位互斥：以前是裸读裸写，回调刚置上的
3184	       * 第二次断连会被这里的清位一并吃掉 —— 槽位就此卡在 READY 而链路已断，
3185	       * 正好是这套 health pump 要防的故障。
3186	       *
3187	       * 三个判断依次做，每个都在锁内重读 state，保持与原来相同的分支顺序
3188	       * （前一步的动作可能把 state 改成 IDLE，进而影响下一步是否该做）。
3189	       */
3190	
3191	      /* 1) HCI 断连事件（回调只置标志，真正回收在这里） */
3192	      act = false;
3193	      pthread_mutex_lock(&g_lock);
3194	      if (slot->hci_gone)
3195	        {
3196	          slot->hci_gone = false;
3197	          reason = slot->hci_reason;
3198	          state  = slot->state;
3199	          act    = true;
3200	        }
3201	
3202	      pthread_mutex_unlock(&g_lock);
3203	
3204	      if (act && state != SENSOR_IDLE)
3205	        {
3206	          LOGI("%s HCI disc reason=0x%02x", kind_name(i), (unsigned)reason);
3207	          g_health_hci_n++;
3208	          slot_handle_disconnected(slot);
3209	        }
3210	
3211	      /* 2) 需要主动拆链 */
3212	      pthread_mutex_lock(&g_lock);
3213	      act = slot->drop_link &&
3214	            slot->state > SENSOR_IDLE &&
3215	            slot->state != SENSOR_DISCONNECTING;
3216	      pthread_mutex_unlock(&g_lock);
3217	
3218	      if (act)
3219	        {
3220	          slot_begin_disconnect(slot, now_ms);
3221	        }
3222	
3223	      /* 3) 拆链超时：重建 GATTC */
3224	      pthread_mutex_lock(&g_lock);
3225	      act = (slot->state == SENSOR_DISCONNECTING &&
3226	             sensor_age_ms(now_ms, slot->state_ms) > SENSOR_HEALTH_DISC_MS);
3227	      pthread_mutex_unlock(&g_lock);
3228	
3229	      if (act)
3230	        {
3231	          LOGI("%s disconnect timeout, recreate GATTC", kind_name(i));
3232	          g_health_disc_to_n++;
3233	          (void)slot_gattc_recreate(slot);
3234	          slot_handle_disconnected(slot);
3235	        }
3236	    }
3237	
3238	  sensor_health_log(now_ms);
3239	}
