3249	 */
3250	void ble_sensor_pump(uint32_t now_ms)
3251	{
3252	  uint8_t i;
3253	  struct sensor_slot *slot;
3254	  bool radio_handled;
3255	
3256	  if (!g_started)
3257	    {
3258	      return;
3259	    }
3260	
3261	  if (g_want_scan && g_scan_until_ms != 0 && now_ms >= g_scan_until_ms)
3262	    {
3263	      ble_sensor_scan_stop();
3264	    }
3265	  else if (g_want_scan && g_scan_until_ms != 0 &&
3266	           (g_adv_debug_ms == 0 ||
3267	            sensor_age_ms(now_ms, g_adv_debug_ms) >= ADV_DEBUG_HEARTBEAT_MS))
3268	    {
3269	      uint32_t left = 0;
3270	
3271	      g_adv_debug_ms = now_ms;
3272	      left = (now_ms < g_scan_until_ms) ?
3273	             (g_scan_until_ms - now_ms) / 1000u : 0;
3274	      scan_progress(left, false);
3275	    }
3276	
3277	  sensor_health_pump(now_ms);
3278	  radio_handled = sensor_reconnect_radio_pump(now_ms);
3279	
3280	  if (sensor_hci_connecting())
3281	    {
3282	      if (g_scanner != NULL)
3283	        {
3284	          sensor_observer_halt();
3285	        }
3286	    }
3287	  else if (g_want_scan && g_scan_duty == SCAN_DUTY_DISCOVERY)
3288	    {
3289	      if ((g_phone_connected || g_phone_adv_held) && g_scanner == NULL)
3290	        {
3291	          (void)sensor_start_scan(SCAN_DUTY_DISCOVERY);
3292	        }
3293	    }
3294	  else if (radio_handled)
3295	    {
3296	      /** ADV / reconnect observer 已由 radio-slot 状态机处理。 */
3297	    }
3298	
3299	  else if (g_scan_until_ms == 0 && sensor_want_reconnect_observer(now_ms))
3300	    {
3301	      sensor_reconnect_scan();
3302	    }
3303	  else if (g_scan_until_ms == 0 && g_want_scan &&
3304	           g_scan_duty == SCAN_DUTY_RECONNECT &&
3305	           !sensor_want_reconnect_observer(now_ms))
3306	    {
3307	      sensor_observer_stop();
3308	    }
3309	  else if (g_want_scan && g_scanner == NULL)
3310	    {
3311	      (void)sensor_start_scan(g_scan_duty);
3312	    }
3313	
3314	  for (i = 0; i < SENSOR_KIND_COUNT; i++)
3315	    {
3316	      slot = &g_slots[i];
3317	      if (!slot->gatt_ok)
3318	        {
3319	          continue;
3320	        }
3321	
3322	      switch (slot->state)
3323	        {
3324	          case SENSOR_IDLE:
3325	            if (slot_keep_link(slot) && slot->adv_seen &&
