3328	              {
3329	                sensor_observer_stop();
3330	                /* 退避窗口里这个分支每个 tick 都成立（retry_ms 的门在
3331	                 * slot_try_connect() 内部），用 LOGI 就是按轮询周期刷屏：
3332	                 * 2026-09-17 实机 0x3e 退避的 3 s 刷了 ~90 行。留在 LOGD
3333	                 * （默认编译掉，CONFIG_MYVENDOR_BLE_COMPANION_DEBUG 打开才
3334	                 * 有）；真正发起连接那一次由 slot_try_connect() 打
3335	                 * "connecting <kind> <addr> rssi="。 */
3336	                LOGD("%s saw advertiser, connecting",
3337	                     kind_name(slot->kind));
3338	              }
3339	
3340	            slot_try_connect(slot, now_ms);
3341	            break;
3342	
3343	          case SENSOR_CONNECTING:
3344	            if (sensor_age_ms(now_ms, slot->state_ms) > SENSOR_CONNECT_MS)
3345	              {
3346	                LOGE("%s connect timeout", kind_name(slot->kind));
3347	                slot_begin_disconnect(slot, now_ms);
3348	              }
3349	            break;
3350	
3351	          case SENSOR_DISCOVERING:
3352	            if (!slot->op_sent)
3353	              {
3354	                bt_uuid_t uuid;
3355	                uint16_t su;
3356	
3357	                /** 等待，避免 ATT 和 LE Read Remote Features 打架。
3358	                 *  先 0x180F 缓存电量，再槽位 UUID（SAL keep_db 追加表）。
3359	                 */
3360	
3361	                if (slot->disc_step == 0 &&
3362	                    sensor_age_ms(now_ms, slot->state_ms) <
3363	                    SENSOR_DISCOVER_DELAY_MS)
3364	                  {
3365	                    break;
3366	                  }
3367	
3368	                su = (slot->disc_step == 0) ?
3369	                     UUID_BAS : kind_svc_uuid(slot->kind);
3370	                uuid = BT_UUID_DECLARE_16(su);
3371	                if (bt_gattc_discover_service(slot->gatt, &uuid) !=
3372	                    BT_STATUS_SUCCESS)
3373	                  {
3374	                    if (slot->disc_step == 0)
3375	                      {
3376	                        LOGI("%s battery discover start failed",
3377	                             kind_name(slot->kind));
3378	                        slot->disc_step = 1;
3379	                        slot->op_sent   = false;
3380	                        slot->state_ms  = now_ms;
3381	                        break;
3382	                      }
3383	
3384	                    LOGE("%s discover start failed", kind_name(slot->kind));
3385	                    slot_begin_disconnect(slot, now_ms);
3386	                  }
3387	                else
3388	                  {
3389	                    slot->op_sent  = true;
3390	                    slot->state_ms = now_ms;
3391	                  }
3392	              }
3393	            else if (sensor_age_ms(now_ms, slot->state_ms) >
3394	                     SENSOR_CONNECT_MS)
3395	              {
3396	                if (slot->disc_step == 0)
3397	                  {
3398	                    LOGI("%s battery discover timeout",
3399	                         kind_name(slot->kind));
3400	                    slot->disc_step = 1;
3401	                    slot->op_sent   = false;
3402	                    slot->state_ms  = now_ms;
3403	                    break;
3404	                  }
3405	
3406	                LOGE("%s discover timeout", kind_name(slot->kind));
3407	                slot_begin_disconnect(slot, now_ms);
3408	              }
3409	            break;
3410	
3411	          case SENSOR_SUBSCRIBING:
3412	            if (!slot->op_sent)
3413	              {
3414	                slot_subscribe_next(slot);
3415	              }
3416	            else if (sensor_age_ms(now_ms, slot->state_ms) >
3417	                     SENSOR_CONNECT_MS)
3418	              {
3419	                LOGE("%s subscribe timeout", kind_name(slot->kind));
3420	                slot_begin_disconnect(slot, now_ms);
3421	              }
3422	            break;
3423	
3424	          case SENSOR_READY:
3425	            if (slot->poll_ms == 0 ||
3426	                sensor_age_ms(now_ms, slot->poll_ms) >= SENSOR_POLL_MS)
3427	              {
3428	                slot->poll_ms = now_ms;
3429	                if (slot->bat_h != 0 && !slot->bat_notify)
3430	                  {
3431	                    (void)bt_gattc_read(slot->gatt, slot->bat_h);
3432	                  }
3433	              }
3434	
3435	            {
3436	              uint32_t ntf_ref = slot->notify_ms != 0 ?
3437	                                 slot->notify_ms : slot->poll_ms;
3438	
3439	              if (slot_keep_link(slot) && ntf_ref != 0 &&
3440	                  sensor_age_ms(now_ms, ntf_ref) > SENSOR_NOTIFY_STALE_MS)
3441	                {
3442	                  if (slot->kind == SENSOR_KIND_HR)
3443	                    {
3444	                      uint16_t h;
3445	
3446	                      h = slot->bat_h != 0 ? slot->bat_h : slot->hr_h;
3447	                      if (slot->probe_sent)
3448	                        {
3449	                          if (sensor_age_ms(now_ms, slot->probe_ms) >
3450	                              SENSOR_PROBE_TIMEOUT_MS)
3451	                            {
3452	                              LOGI("%s notify stale, reconnect",
3453	                                   kind_name(slot->kind));
3454	                              slot_begin_disconnect(slot, now_ms);
3455	                            }
3456	                        }
3457	                      else if (h != 0 &&
3458	                               bt_gattc_read(slot->gatt, h) ==
3459	                               BT_STATUS_SUCCESS)
3460	                        {
3461	                          slot->probe_sent = true;
3462	                          slot->probe_ms   = now_ms;
3463	                          LOGI("%s notify stale, ATT probe",
3464	                               kind_name(slot->kind));
3465	                        }
3466	                      else
3467	                        {
3468	                          LOGI("%s notify stale, reconnect",
3469	                               kind_name(slot->kind));
3470	                          slot_begin_disconnect(slot, now_ms);
3471	                        }
3472	                    }
3473	                  else
3474	                    {
3475	                      slot->meas_idle = true;
3476	                    }
3477	                }
3478	            }
3479	
3480	            slot_idle_link_check(slot, now_ms);
3481	            break;
3482	
3483	          case SENSOR_DISCONNECTING:
3484	            break;
3485	
3486	          default:
3487	            break;
3488	        }
3489	
3490	      if (slot->drop_link &&
3491	          slot->state > SENSOR_IDLE &&
3492	          slot->state != SENSOR_DISCONNECTING)
3493	        {
3494	          slot_begin_disconnect(slot, now_ms);
3495	        }
3496	    }
3497	
3498	  {
3499	    bool any = false;
3500	
3501	    for (i = 0; i < SENSOR_KIND_COUNT; i++)
3502	      {
3503	        if (slot_linked(&g_slots[i]))
3504	          {
3505	            any = true;
3506	            break;
3507	          }
3508	      }
3509	
3510	    if (g_adv_debug && any &&
3511	        (g_linked_print_ms == 0 ||
3512	         sensor_age_ms(now_ms, g_linked_print_ms) >= SENSOR_POLL_MS))
3513	      {
