1788	              (attr_handle == slot->bat_h || attr_handle == slot->csc_h ||
1789	               attr_handle == slot->cps_h || attr_handle == slot->hr_h);
1790	  if (was_probe)
1791	    {
1792	      slot->probe_sent = false;
1793	    }
